INSERT INTO translation_meta (key, value) VALUES ('license_url', 'https://creativecommons.org/licenses/by-sa/4.0/deed.pt-br');
INSERT INTO books (id, name, testament, order_index) VALUES ('JHN', 'João', 'NT', 43);
INSERT INTO chapters (id, book_id, chapter_number) VALUES ('JHN.1', 'JHN', 1);
INSERT INTO chapters (id, book_id, chapter_number) VALUES ('JHN.2', 'JHN', 2);
INSERT INTO chapters (id, book_id, chapter_number) VALUES ('JHN.3', 'JHN', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.1', 'JHN.1', 'JHN', 1, 1, 'Ἐν ἀρχῇ ἦν ὁ λόγος, καὶ ὁ λόγος ἦν πρὸς τὸν θεόν, καὶ θεὸς ἦν ὁ λόγος.', 'No princípio era o Verbo/Palavra, e o Verbo/Palavra estava com o Deus, e Deus era o Verbo/Palavra.', 'No princípio era a Palavra, e a Palavra estava face a face com Deus, e a Palavra era Deus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.1', 'Palavra', 'ὁ λόγος - *ho logos*', 'O termo *logos* carrega peso tanto no pensamento judaico (a *Memra* ou Palavra criadora de Yahweh no Antigo Testamento e Targuns) quanto no helênico (a razão ordenadora do cosmos). Em português, mantemos ''a Palavra'' com inicial maiúscula para expressar a pessoalidade pré-encarnada do Filho.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.1', 'face a face com', 'πρὸς τὸν θεόν - *pros ton theon*', 'A preposição *pros* com caso acusativo sugere relação íntima, comunhão pessoal e movimento contínuo em direção ao outro, e não mera localização espacial estática.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.1', 'era Deus', 'θεὸς ἦν ὁ λόγος - *theos ēn ho logos*', '*Theos* não possui o artigo definido neste ponto da oração, enquanto *logos* possui (*ho logos*). Gramaticalmente (seguindo a regra de Colwell e a análise de Philip Harner), *theos* funciona como predicativo pré-posto qualitativo, definindo a natureza e essência plenamente divina da Palavra sem confundi-la ontologicamente com a pessoa do Pai (*o Deus* citado na cláusula anterior).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.2', 'JHN.1', 'JHN', 1, 2, 'οὗτος ἦν ἐν ἀρχῇ πρὸς τὸν θεόν.', 'Este estava no princípio com o Deus.', 'Ele estava no princípio face a face com Deus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.2', 'Ele', 'οὗτος - *houtos*', 'Pronome demonstrativo enfático que resume e amarra as três afirmações do v. 1, reforçando a identidade contínua do Logos em Sua comunhão eterna com o Pai antes de qualquer ato da criação.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.2', 'no princípio', 'ἐν ἀρχῇ - *en archē*', 'Eco deliberado de Gênesis 1:1 (*Bereshit*). Enquanto Gênesis marca o início temporal da matéria e do cosmos ("criou Deus"), o verbo imperfeito grego *ēn* ("era/já existia") em João indica existência atemporal e contínua que antecede o próprio início do tempo.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.3', 'JHN.1', 'JHN', 1, 3, 'πάντα δι’ αὐτοῦ ἐγένετο, καὶ χωρὶς αὐτοῦ ἐγένετο οὐδὲ ἕν. ὃ γέγονεν', 'Todas as coisas por meio dele vieram a ser, e sem ele veio a ser nem uma só coisa que veio a ser.', 'Tudo veio a existir por meio dele, e sem ele nada do que existe veio a existir.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.3', 'Por meio dele', 'δι’ αὐτοῦ - *di’ autou*', 'A preposição *dia* com genitivo denota o agente intermediário pelo qual a criação opera. Deus Pai cria tudo mediante o Filho (cf. Cl 1:16; Hb 1:2).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.3', 'vieram a existir', 'ἐγένετο - *egeneto*', 'O verbo muda de *ēn* (imperfeito de ser/existir no v. 1-2) para *egeneto* (aoristo de vir a existir / ser criado). O Logos *é*; o universo *veio a ser*.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.3', 'absolutamente nada', 'οὐδὲ ἕν - *oude hen*', 'Negação enfática ("nem sequer uma única coisa"), ressaltando a totalidade absoluta da soberania criadora do Logos contra concepções gnósticas de emanações intermediárias autônomas.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.4', 'JHN.1', 'JHN', 1, 4, 'ἐν αὐτῷ ζωὴ ἦν, καὶ ἡ ζωὴ ἦν τὸ φῶς τῶν ἀνθρώπων·', 'Nele vida era, e a vida era a luz dos homens;', 'Nele estava a vida, e a vida era a luz dos homens.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.4', 'vida', 'ζωή - *zōē*', 'João não emprega *bios* (vida biológica/fisiológica transitória), mas *zōē*, referindo-se ao princípio divino e imperecível da vida incriada, a vida eterna que emana de Deus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.4', 'luz dos homens', 'τὸ φῶς τῶν ἀνθρώπων - *to phōs tōn anthrōpōn*', 'A vida no Logos não é passiva; ela se projeta como revelação, discernimento ético, espiritual e intelectual sobre toda a raça humana (*anthrōpoi*).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.5', 'JHN.1', 'JHN', 1, 5, 'καὶ τὸ φῶς ἐν τῇ σκοτίᾳ φαίνει, καὶ ἡ σκοτία αὐτὸ οὐ κατέλαβεν.', 'E a luz na escuridão brilha, e a escuridão ela não apreendeu/compreendeu.', 'A luz brilha na escuridão, e a escuridão não a venceu.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.5', 'brilha', 'φαίνει - *phainei*', 'Verbo no presente do indicativo, enfatizando ação contínua: a luz permanece brilhando ininterruptamente no mundo tenebroso.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.5', 'não a venceu', 'αὐτὸ οὐ κατέλαβεν - *auto ou katelaben*', 'O verbo *katalambanō* tem um duplo sentido poético e teológico deliberado: significa tanto "compreender/apreender cognitivamente" quanto "subjugar/vencer/apagar". As trevas não apenas falharam em entender a luz, como foram incapazes de derrotá-la ou sufocá-la.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.6', 'JHN.1', 'JHN', 1, 6, 'Ἐγένετο ἄνθρωπος, ἀπεσταλμένος παρὰ θεοῦ, ὄνομα αὐτῷ Ἰωάννης·', 'Veio a haver um homem, enviado da parte de Deus, nome para ele João;', 'Surgiu um homem, enviado por Deus; seu nome era João.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.6', 'Surgiu', 'Ἐγένετο - *Egeneto*', 'Em marcante contraste com o Logos que "era" (*ēn*), João Batista "veio a ser / apareceu no cenário histórico" (*egeneto*), demonstrando sua condição finita de criatura.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.6', 'enviado por Deus', 'ἀπεσταλμένος παρὰ θεοῦ - *apestalmenos para theou*', 'Particípio perfeito passivo do verbo *apostellō*, indicando uma comissão profética divina que confere a João a autoridade permanente de arauto legítimo da revelação.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.7', 'JHN.1', 'JHN', 1, 7, 'οὗτος ἦλθεν εἰς μαρτυρίαν ἵνα μαρτυρήσῃ περὶ τοῦ φωτός, ἵνα πάντες πιστεύσωσιν δι’ αὐτοῦ.', 'Este veio para testemunho a fim de que testemunhasse acerca da luz, para que todos cressem por meio dele.', 'Ele veio como testemunha, para testemunhar a respeito da luz, para que todos cressem por meio dele.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.7', 'testemunho / testemunhar', 'μαρτυρίαν / μαρτυρήσῃ - *martyrian / martyrēsē*', 'A família lexical do termo jurídico *martyria* é um dos temas fundamentais do Quarto Evangelho. O papel de João Batista não era ser a fonte da salvação, mas fornecer um depoimento histórico confiável e fidedigno perante o tribunal do mundo.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.7', 'para que todos cressem', 'ἵνα πάντες πιστεύσωσιν - *hina pantes pisteusōsin*', 'Oração subordinada final com conjunção *hina* e verbo no subjuntivo aoristo (*pisteusōsin*), indicando o propósito evangelístico universal do testemunho profético: conduzir pessoas à decisão de fé no Messias.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.8', 'JHN.1', 'JHN', 1, 8, 'οὐκ ἦν ἐκεῖνος τὸ φῶς, ἀλλ’ ἵνα μαρτυρήσῃ περὶ τοῦ φωτός.', 'Não era aquele a luz, mas para que testemunhasse acerca da luz.', 'Não era ele a luz, mas veio para testemunhar a respeito da luz.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.8', 'Ele próprio não era a luz', 'οὐκ ἦν ἐκεῖνος τὸ φῶς - *ouk ēn ekeinos to phōs*', 'Esclarecimento de caráter polêmico e apologético contra seitas do primeiro e segundo séculos (como círculos mandeanos ou discípulos remanescentes de João Batista em Éfeso) que superestimavam a figura de João Batista em detrimento de Jesus (cf. At 19:1-7).', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.9', 'JHN.1', 'JHN', 1, 9, 'Ἦν τὸ φῶς τὸ ἀληθινόν, ὃ φωτίζει πάντα ἄνθρωπον, ἐρχόμενον εἰς τὸν κόσμον.', 'Era a luz a verdadeira, que ilumina todo homem, vindo ao mundo.', 'A luz verdadeira, que ilumina todo ser humano, estava vindo ao mundo.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.9', 'a luz verdadeira', 'τὸ φῶς τὸ ἀληθινόν - *to phōs to alēthinon*', 'O adjetivo *alēthinos* denota aquilo que é genuíno, real, autêntico e supremo em contraste com representações imperfeitas, tipológicas ou sombras do Antigo Testamento.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.9', 'estava vindo ao mundo', 'ἦν ... ἐρχόμενον εἰς τὸν κόσμον - *ēn ... erchomenon eis ton kosmon*', 'Construção perífrástica com o particípio neutro *erchomenon* concordando com *to phōs*, descrevendo o processo histórico da Encarnação como a vinda da luz definitiva ao cosmos.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.10', 'JHN.1', 'JHN', 1, 10, 'ἐν τῷ κόσμῳ ἦν, καὶ ὁ κόσμος δι’ αὐτοῦ ἐγένετο, καὶ ὁ κόσμος αὐτὸν οὐκ ἔγνω.', 'No mundo estava, e o mundo por meio dele veio a ser, e o mundo a ele não conheceu.', 'Ele estava no mundo, e o mundo veio a existir por meio dele, e o mundo não o reconheceu.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.10', 'o mundo', 'ὁ κόσμος - *ho kosmos*', 'No vocabulário joanino, *kosmos* tem triplo significado: a ordem criada (v. 10b), o teatro da humanidade (v. 9), e o sistema humano em rebelião hostil contra Deus (v. 10c).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.10', 'não o reconheceu', 'αὐτὸν οὐκ ἔγνω - *auton ouk egnō*', 'O verbo *ginōskō* (no aoristo ativo) aponta para um conhecimento íntimo, relacional e de submissão pactual. A tragédia cósmica é que a criação rejeitou seu próprio Arquiteto e Sustentador.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.11', 'JHN.1', 'JHN', 1, 11, 'εἰς τὰ ἴδια ἦλθεν, καὶ οἱ ἴδιοι αὐτὸν οὐ παρέλαβον.', 'Para as próprias coisas veio, e os próprios a ele não receberam.', 'Veio para o que era seu, e os seus não o acolheram.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.11', 'o que era seu', 'τὰ ἴδια - *ta idia*', 'O neutro plural refere-se ao território, à terra da promessa, ao Templo e à herança de Israel.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.11', 'os seus', 'οἱ ἴδιοι - *hoi idioi*', 'O masculino plural aponta especificamente para o povo da aliança (o povo judeu), que, detendo as profecias e a Lei, falhou em receber e acolher (*parelabon*) o Messias enviado.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.12', 'JHN.1', 'JHN', 1, 12, 'ὅσοι δὲ ἔλαβον αὐτόν, ἔδωκεν αὐτοῖς ἐξουσίαν τέκνα θεοῦ γενέσθαι, τοῖς πιστεύουσιν εἰς τὸ ὄνομα αὐτοῦ,', 'Quantos porém receberam a ele, deu a eles autoridade/direito filhos de Deus tornarem-se, aos que creem no nome dele,', 'Mas a todos que o receberam ele deu o direito de se tornarem filhos de Deus — aos que creem no seu nome.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.12', 'o direito', 'ἐξουσίαν - *exousian*', '*Exousia* abrange tanto a capacidade legal/direito outorgado quanto o poder e prerrogativa espiritual de ingressar na família de Deus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.12', 'filhos de Deus', 'τέκνα θεοῦ - *tekna theou*', 'João reserva rigorosamente a palavra *huios* (filho em sentido ontológico único) para Jesus Cristo, enquanto emprega *tekna* (filhos gerados por novo nascimento e afeto) para os crentes redimidos.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.12', 'creem no seu nome', 'τοῖς πιστεύουσιν εἰς τὸ ὄνομα αὐτοῦ - *tois pisteuousin eis to onoma autou*', 'O particípio com a preposição *eis* denota um movimento de entrega total, confiança e união existencial com a pessoa e autoridade representadas pelo "Nome" de Cristo.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.13', 'JHN.1', 'JHN', 1, 13, 'οἳ οὐκ ἐξ αἱμάτων οὐδὲ ἐκ θελήματος σαρκὸς οὐδὲ ἐκ θελήματος ἀνδρὸς ἀλλ’ ἐκ θεοῦ ἐγεννήθησαν.', 'os quais não de sangues nem da vontade da carne nem da vontade de varão/marido, mas de Deus foram gerados.', 'Eles não foram gerados de sangue, nem da vontade da carne, nem da vontade de homem, mas de Deus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.13', 'não de sangues', 'οὐκ ἐξ αἱμάτων - *ouk ex haimatōn*', 'O uso do plural *haimata* (''sangues'') alude à linhagem genealógica e herança biológica aristocrática. O pertencimento à família de Deus não é transmitido por hereditariedade étnica.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.13', 'nem da vontade da carne... nem da vontade de varão', 'οὐδὲ ἐκ θελήματος σαρκὸς οὐδὲ ἐκ θελήματος ἀνδρὸς - *oude ek thelēmatos sarkos oude ek thelēmatos andros*', 'Exclui qualquer iniciativa hormonal, sexual ou decisão patriarcal humana. O novo nascimento é uma obra monergística originada soberanamente em Deus (*ek theou egennēthēsan*).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.14', 'JHN.1', 'JHN', 1, 14, 'Καὶ ὁ λόγος σὰρξ ἐγένετο καὶ ἐσκήνωσεν ἐν ἡμῖν, καὶ ἐθεασάμεθα τὴν δόξαν αὐτοῦ, δόξαν ὡς μονογενοῦς παρὰ πατρός, πλήρης χάριτος καὶ ἀληθείας.', 'E o Verbo carne veio a ser e tabernaculou entre nós, e contemplamos a glória dele, glória como de unigênito da parte do Pai, cheio de graça e verdade.', 'E a Palavra se fez carne e armou sua tenda entre nós. E contemplamos a sua glória, glória como a do Filho único, vindo do Pai, cheio de graça e de verdade.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.14', 'se fez carne', 'σὰρξ ἐγένετο - *sarx egeneto*', 'O clímax do prólogo. O Logos eterno e transcendente assumiu a fragilidade da natureza humana finita e concreta (*sarx*), sem deixar de ser Deus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.14', 'armou sua tenda entre nós', 'ἐσκήνωσεν ἐν ἡμῖν - *eskēnōsen en hēmin*', 'Do verbo *skēnoō*, que significa literalmente "armar tenda" ou "tabernacular". Alusão direta ao Tabernáculo no deserto, onde o Deus invisível habitava visivelmente no meio do Seu povo através da nuvem da *Shekinah*.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.14', 'contemplamos', 'ἐθεασάμεθα - *etheasametha*', 'Do verbo *theaomai*, que significa observar com atenção cuidadosa, como testemunhas oculares de um acontecimento histórico factual.', 3);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.14', 'Filho único', 'μονογενοῦς - *monogenous*', 'Derivado de *monos* (único) e *genos* (espécie/categoria). O termo enfatiza a singularidade ímpar e a relação única do Filho com o Pai, e não um ato de procriação temporal.', 4);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.14', 'graça e verdade', 'χάριτος καὶ ἀληθείας - *charitos kai alētheias*', 'Tradução grega direta do binômio hebraico fundamental da aliança de Deus em Êxodo 34:6 (*Hesed ve-Emet* - amor leal e fidelidade inabalável). Jesus é a personificação viva da aliança de Yahweh.', 5);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.15', 'JHN.1', 'JHN', 1, 15, 'Ἰωάννης μαρτυρεῖ περὶ αὐτοῦ καὶ κέκραγεν λέγων· Οὗτος ἦν ὃν εἶπον· Ὁ ὀπίσω μου ἐρχόμενος ἔμπροσθέν μου γέγονεν, ὅτι πρῶτός μου ἦν.', 'João testemunha acerca dele e clamou dizendo: Este era de quem eu disse: O atrás de mim vindo adiante de mim passou a ser, porque primeiro de mim era.', 'João testemunha a respeito dele e clama: “Era este que eu dizia: Aquele que vem depois de mim passou à minha frente, porque existia antes de mim”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.15', 'clama', 'κέκραγεν - *kekragen*', 'Perfeito grego com força de presente contínuo intensivo, denotando um clamor público vigoroso, solene e com autoridade profética indiscutível.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.15', 'passou à minha frente... existia antes de mim', 'ἔμπροσθέν μου γέγονεν, ὅτι πρῶτός μου ἦν - *emprosthen mou gegonen, hoti prōtos mou ēn*', 'Jogo de palavras cronológico e hierárquico. Historicamente, João Batista nasceu antes de Jesus de acordo com a carne (Lc 1:36); no entanto, na ordem de dignidade messiânica (*emprosthen*) e de preexistência eterna (*prōtos*), Cristo transcende infinitamente o precursor.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.16', 'JHN.1', 'JHN', 1, 16, 'ὅτι ἐκ τοῦ πληρώματος αὐτοῦ ἡμεῖς πάντες ἐλάβομεν, καὶ χάριν ἀντὶ χάριτος·', 'Porque da plenitude dele nós todos recebemos, e graça em lugar de graça.', 'Pois de sua plenitude todos nós recebemos, e graça sobre graça.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.16', 'plenitude', 'πληρώματος - *plērōmatos*', 'A totalidade inexaurível dos atributos divinos, virtudes e recursos redentivos que habitam corporalmente em Cristo (cf. Cl 2:9).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.16', 'graça sobre graça', 'χάριν ἀντὶ χάριτος - *charin anti charitos*', 'A preposição *anti* aqui indica substituição cumulativa e sucessão ininterrupta ("uma graça que sucede e amplia outra graça"), apontando para as ondas infindáveis do favor divino concedidas àqueles que estão em Cristo.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.17', 'JHN.1', 'JHN', 1, 17, 'ὅτι ὁ νόμος διὰ Μωϋσέως ἐδόθη, ἡ χάρις καὶ ἡ ἀλήθεια διὰ Ἰησοῦ Χριστοῦ ἐγένετο.', 'Porque a lei por meio de Moisés foi dada, a graça e a verdade por meio de Jesus Cristo vieram a ser.', 'Porque a Lei foi dada por meio de Moisés; a graça e a verdade vieram a existir por meio de Jesus Cristo.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.17', 'a Lei foi dada... a graça e a verdade vieram', 'ὁ νόμος ἐδόθη ... ἡ χάρις καὶ ἡ ἀλήθεια ἐγένετο - *ho nomos edothē ... hē charis kai hē alētheia egeneto*', 'Contraste teológico entre a promulgação externa da Torá mediante um mediador humano (*edothē dia Mōuseōs*) e a manifestação encarnada e viva do amor pactual de Deus personificado na história (*egeneto dia Iēsou Christou*).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.17', 'Jesus Cristo', 'Ἰησοῦ Χριστοῦ - *Iēsou Christou*', 'Primeira menção expressa do nome histórico e do título messiânico no Evangelho de João, identificando formalmente a ''Palavra'' dos vv. 1-14 com Jesus de Nazaré, o Ungido de Deus.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.18', 'JHN.1', 'JHN', 1, 18, 'θεὸν οὐδεὶς ἑώρακεν πώποτε· μονογενὴς θεὸς ὁ ὢν εἰς τὸν κόλπον τοῦ πατρὸς ἐκεῖνος ἐξηγήσατο.', 'A Deus ninguém viu jamais; o Deus unigênito, aquele que está no seio do Pai, aquele o revelou/explicou.', 'Ninguém jamais viu a Deus; o Filho único, que é Deus e está no seio do Pai, ele o revelou.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.18', 'o Filho único, que é Deus', 'μονογενὴς θεὸς - *monogenēs theos*', 'A leitura textual mais antiga e fidedigna dos manuscritos papiros gregos (\(\mathfrak{P}^{66}\), \(\mathfrak{P}^{75}\), Códice Sinaítico e Vaticano) traz *monogenēs theos* ("Deus unigênito" ou "o Deus único"). Isso conclui o prólogo fechando uma inclusão perfeita com João 1:1c (*theos ēn ho logos*), afirmando inequivocamente a divindade plena do Filho.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.18', 'no seio do Pai', 'εἰς τὸν κόλπον τοῦ πατρὸς - *eis ton kolpon tou patros*', 'Metáfora hebraico-oriental de carinho supremo, intimidade profunda e comunhão ininterrupta (como no banquete, reclinar-se no peito do anfitrião; cf. Jo 13:23).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.18', 'o revelou', 'ἐξηγήσατο - *exēgēsato*', 'Aoristo indicativo do verbo *exēgeomai*, de onde provém a palavra moderna "exegese". O termo significa "narrar detalhadamente", "tornar conhecido", "explicar e desdobrar o sentido". Jesus Cristo é o intérprete e a exegese viva e definitiva de Deus para a humanidade.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.19', 'JHN.1', 'JHN', 1, 19, 'Καὶ αὕτη ἐστὶν ἡ μαρτυρία τοῦ Ἰωάννου, ὅτε ἀπέστειλαν πρὸς αὐτὸν οἱ Ἰουδαῖοι ἐξ Ἱεροσολύμων ἱερεῖς καὶ Λευίτας ἵνα ἐρωτήσωσιν αὐτόν· Σὺ τίς εἶ;', 'E este é o testemunho do João, quando enviaram a ele os judeus de Jerusalém sacerdotes e levitas para que perguntassem a ele: Tu quem és?', 'Este é o testemunho de João, quando as autoridades judaicas de Jerusalém lhe enviaram sacerdotes e levitas para lhe perguntarem: “Quem é você?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.19', 'as autoridades judaicas', 'οἱ Ἰουδαῖοι - *hoi Ioudaioi*', 'No Quarto Evangelho, o termo refere-se frequentemente não ao povo judeu em geral, mas à liderança religiosa, aristocrática e sacerdotal sediada em Jerusalém (o Sinédrio).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.19', 'sacerdotes e levitas', 'ἱερεῖς καὶ Λευίτας - *hiereis kai Leuitas*', 'Funcionários encarregados do culto e da guarda do Templo. Sua delegação oficial demonstra a enorme comoção pública que o ministério de João Batista causava na Judeia.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.20', 'JHN.1', 'JHN', 1, 20, 'καὶ ὡμολόγησεν καὶ οὐκ ἠρνήσατο, καὶ ὡμολόγησεν ὅτι Ἐγὼ οὐκ εἰμὶ ὁ Χριστός.', 'E confessou e não negou, e confessou que: Eu não sou o Cristo.', 'Ele confessou e não negou; confessou: “Eu não sou o Cristo”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.20', 'confessou e não negou', 'ὡμολόγησεν καὶ οὐκ ἠρνήσατο - *hōmologēsen kai ouk ērnēsato*', 'Construção enfática hebraica por paralelismo antitético (afirmação positiva seguida de negação do oposto), sublinhando a total recusa de João em aceitar títulos messiânicos indevidos.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.20', 'Eu não sou o Cristo', 'Ἐγὼ οὐκ εἰμὶ ὁ Χριστός - *Egō ouk eimi ho Christos*', 'O pronome *Egō* é colocado em posição de destaque na oração, preparando o contraste com o "Eu Sou" (*Egō eimi*) divino que Jesus proferirá ao longo do Evangelho.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.21', 'JHN.1', 'JHN', 1, 21, 'καὶ ἠρώτησαν αὐτόν· Τί οὖν; Σὺ Ἠλίας εἶ; καὶ λέγει· Οὐκ εἰμί. Ὁ προφήτης εἶ σύ; καὶ ἀπεκρίθη· Οὔ.', 'E perguntaram a ele: O que então? Tu Elias és? E diz: Não sou. O profeta és tu? E respondeu: Não.', 'Perguntaram-lhe: “O que, então? Você é Elias?”. Ele disse: “Não sou”. “Você é o Profeta?”. E respondeu: “Não”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.21', 'É Elias?', 'Ἠλίας εἶ - *Ēlias ei*', 'Baseado na profecia de Malaquias 4:5, os judeus esperavam o retorno literal do profeta Elias antes do "Dia do Senhor". Embora João ministrasse no espírito e poder de Elias (Lc 1:17; Mt 11:14), ele não era a reencarnação física literal de Elias.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.21', 'o Profeta', 'Ὁ προφήτης - *Ho prophētēs*', 'Alusão ao "profeta semelhante a Moisés" prometido em Deuteronômio 18:15-18, uma figura escatológica proeminente nas expectativas messiânicas do Segundo Templo.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.22', 'JHN.1', 'JHN', 1, 22, 'εἶπαν οὖν αὐτῷ· Τίς εἶ; ἵνα ἀπόκρισιν δῶμεν τοῖς πέμψασιν ἡμᾶς· τί λέγεις περὶ σεαυτοῦ;', 'Disseram então a ele: Quem és? Para que resposta demos aos que enviaram a nós; que dizes acerca de ti mesmo?', 'Disseram-lhe então: “Quem é você? Precisamos levar uma resposta aos que nos enviaram. O que você diz de si mesmo?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.22', 'resposta àqueles que nos enviaram', 'ἀπόκρισιν δῶμεν τοῖς πέμψασιν ἡμᾶς - *apokrisin dōmen tois pempsasin hēmas*', 'Os emissários operavam sob mandato institucional rígido do Sinédrio de Jerusalém, exigindo uma autodefinição formal e pública.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.23', 'JHN.1', 'JHN', 1, 23, 'ἔφη· Ἐγὼ φωνὴ βοῶντος ἐν τῇ ἐρήμῳ· Εὐθύνατε τὴν ὁδὸν κυρίου, καθὼς εἶπεν Ἡσαΐας ὁ προφήτης.', 'Disse: Eu voz de um clamando no deserto: Endireitai o caminho do Senhor, como disse Isaías o profeta.', 'Ele disse: “Eu sou a voz de quem clama no deserto: Endireitem o caminho do Senhor” — como disse o profeta Isaías.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.23', 'ESCRITURA', 21, 81, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.23', 'voz de quem clama no deserto', 'φωνὴ βοῶντος ἐν τῇ ἐρήμῳ - *phōnē boōntos en tē erēmō*', 'Citação direta de Isaías 40:3. João se recusa a reivindicar qualquer dignidade pessoal ou título; ele se define meramente como um instrumento sonoro (*phōnē*), o arauto que prepara a rota régia para a chegada iminente do Rei e Senhor (*Kyrios*).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.23', 'no deserto', 'ἐν τῇ ἐρήμῳ - *en tē erēmō*', 'No imaginário judaico, o deserto era o lugar da aliança originária, do novo êxodo profético e da restauração messiânica.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.24', 'JHN.1', 'JHN', 1, 24, 'Καὶ ἀπεσταλμένοι ἦσαν ἐκ τῶν Φαρισαίων.', 'E os enviados eram dentre os fariseus.', 'Ora, os que haviam sido enviados eram do meio dos fariseus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.24', 'fariseus', 'ἐκ τῶν Φαρισαίων - *ek tōn Pharisaiōn*', 'Grupo rigorista dedicado à observância minuciosa da pureza ritual e das tradições orais (*Halakha*). Como guardiões das normas de purificação, a prática do batismo por João despertava profundo escrutínio teológico entre eles.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.25', 'JHN.1', 'JHN', 1, 25, 'καὶ ἠρώτησαν αὐτὸν καὶ εἶπαν αὐτῷ· Τί οὖν βαπτίζεις εἰ σὺ οὐκ εἶ ὁ Χριστὸς οὐδὲ Ἠλίας οὐδὲ ὁ προφήτης;', 'E perguntaram a ele e disseram a ele: Por que então batizas se tu não és o Cristo nem Elias nem o profeta?', 'Perguntaram-lhe: “Então por que você batiza, se não é o Cristo, nem Elias, nem o Profeta?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.25', 'por que você batiza?', 'Τί οὖν βαπτίζεις - *Ti oun baptizeis*', 'Na tradição judaica, o batismo por imersão (*tevilah*) era comum para a conversão de gentios (prosélitos). O fato de João exigir batismo de arrependimento dos próprios judeus nascidos implicava que toda a nação necessitava de renovação espiritual radical diante da era messiânica.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.26', 'JHN.1', 'JHN', 1, 26, 'ἀπεκρίθη αὐτοῖς ὁ Ἰωάννης λέγων· Ἐγὼ βαπτίζω ἐν ὕδατι· μέσος ὑμῶν ἕστηκεν ὃν ὑμεῖς οὐκ οἴδατε,', 'Respondeu a eles o João dizendo: Eu batizo em água; no meio de vós está em pé a quem vós não conheceis,', 'João lhes respondeu: “Eu batizo com água. No meio de vocês está alguém que vocês não conhecem,');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.26', 'batizo com água', 'βαπτίζω ἐν ὕδατι - *baptizō en hydati*', 'Estabelece o caráter preparatório e exterior do seu ministério, que aponta para o batismo no Espírito Santo a ser efetuado pelo Messias (cf. v. 33).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.26', 'no meio de vocês está', 'μέσος ὑμῶν ἕστηκεν - *mesos hymōn hestēken*', 'Perfeito indicativo *hestēken*, indicando que o Messias já se encontra fisicamente presente no seio da sociedade judaica, de forma anônima e despercebida pela liderança religiosa.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.27', 'JHN.1', 'JHN', 1, 27, 'ὁ ὀπίσω μου ἐρχόμενος, οὗ οὐκ εἰμὶ [ἐγὼ] ἄξιος ἵνα λύσω αὐτοῦ τὸν ἱμάντα τοῦ ὑποδήματος.', 'o atrás de mim vindo, do qual não sou digno para que desate dele a correia da sandália.', 'aquele que vem depois de mim, de quem não sou digno de desatar a correia da sandália”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.27', 'desatar a correia da sandália', 'λύσω αὐτοῦ τὸν ἱμάντα τοῦ ὑποδήματος - *lysō autou ton himanta tou hypodēmatos*', 'De acordo com a tradição rabínica (Talmude Babilônico, *Ketubot* 96a), um discípulo devia prestar todos os serviços ao seu mestre, exceto desatar suas sandálias, tarefa considerada excessivamente humilhante e reservada aos escravos gentios não-judeus. João declara que sua dignidade diante de Cristo é inferior à do mais humilde escravo.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.28', 'JHN.1', 'JHN', 1, 28, 'Ταῦτα ἐν Βηθανίᾳ ἐγένετο πέραν τοῦ Ἰορδάνου, ὅπου ἦν ὁ Ἰωάννης βαπτίζων.', 'Estas coisas em Betânia aconteceram além do Jordão, onde estava o João batizando.', 'Isso aconteceu em Betânia, do outro lado do Jordão, onde João estava batizando.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.28', 'Betânia além do Jordão', 'Βηθανίᾳ πέραν τοῦ Ἰορδάνου - *Bēthania peran tou Iordanou*', 'Diferente da Betânia próxima a Jerusalém (lar de Lázaro, Marta e Maria), este local ficava na região da Pereia, no lado leste do Jordão, local seguro fora da jurisdição direta da Judeia.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.29', 'JHN.1', 'JHN', 1, 29, 'Τῇ ἐπαύριον βλέπει τὸν Ἰησοῦν ἐρχόμενον πρὸς αὐτόν, καὶ λέγει· Ἴδε ὁ ἀμνὸς τοῦ θεοῦ ὁ αἴρων τὴν ἁμαρτίαν τοῦ κόσμου.', 'No dia seguinte vê o Jesus vindo para ele, e diz: Eis o cordeiro do Deus, o que tira o pecado do mundo.', 'No dia seguinte, João viu Jesus vindo em sua direção e disse: “Eis o Cordeiro de Deus, que tira o pecado do mundo!');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.29', 'No dia seguinte', 'Τῇ ἐπαύριον - *Tē epaurion*', 'João estrutura o capítulo 1 em uma sequência de dias consecutivos (vv. 19, 29, 35, 43 e 2:1), ecoando a semana inaugural da criação em Gênesis para inaugurar a Nova Criação em Cristo.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.29', 'o Cordeiro de Deus', 'ὁ ἀμνὸς τοῦ θεοῦ - *ho amnos tou theou*', 'Síntese teológica profunda que evoca: 1) o Cordeiro Pascal (*Pesach* - Êx 12) cuja aspersão liberta da morte; 2) o Servo Sofredor conduzido como cordeiro ao matadouro pelos nossos pecados (Is 53:7); 3) o sacrifício diário contínuo do Templo (*Tamid*).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.29', 'que tira o pecado do mundo', 'ὁ αἴρων τὴν ἁμαρτίαν τοῦ κόσμου - *ho airōn tēn hamartian tou kosmou*', 'O particípio presente *airōn* expressa uma ação contínua e eficaz de expiar, carregar sobre si e remover a culpa cósmica da humanidade (*kosmos*). O substantivo *hamartia* está no singular ("o pecado"), referindo-se ao princípio e à raiz de toda rebelião contra Deus.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.30', 'JHN.1', 'JHN', 1, 30, 'οὗτός ἐστιν ὑπὲρ οὗ ἐγὼ εἶπον· Ὀπίσω μου ἔρχεται ἀνὴρ ὃς ἔμπροσθέν μου γέγονεν, ὅτι πρῶτός μου ἦν.', 'Este é em favor de quem eu disse: Atrás de mim vem um varão que adiante de mim passou a ser, porque primeiro de mim era.', 'É a respeito dele que eu disse: ‘Depois de mim vem um homem que passou à minha frente, porque existia antes de mim’.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.30', 'um homem', 'ἀνὴρ - *anēr*', 'Diferente de *anthrōpos* (ser humano genérico), *anēr* designa especificamente um homem adulto e distinto, enfatizando a plena humanidade e identidade histórica de Jesus.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.31', 'JHN.1', 'JHN', 1, 31, 'κἀγὼ οὐκ ᾔδειν αὐτόν, ἀλλ’ ἵνα φανερωθῇ τῷ Ἰσραὴλ διὰ τοῦτο ἦλθον ἐγὼ ἐν ὕδατι βαπτίζων.', 'E eu não o conhecia, mas para que fosse manifestado ao Israel por isso vim eu em água batizando.', 'Eu não o conhecia; mas foi para que ele fosse manifestado a Israel que eu vim batizando com água”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.31', 'não o conhecia', 'οὐκ ᾔδειν αὐτόν - *ouk ēdein auton*', 'João e Jesus eram parentes biológicos (Lc 1:36), mas João não compreendia de antemão a plenitude do chamado messiânico e divino de Jesus até a confirmação sobrenatural do sinal celestial (v. 33).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.31', 'manifestado a Israel', 'φανερωθῇ τῷ Ἰσραὴλ - *phanerōthē tō Israēl*', 'O propósito primordial do ministério de João Batista era servir de palco público para a epifania de Cristo diante do povo da aliança.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.32', 'JHN.1', 'JHN', 1, 32, 'Καὶ ἐμαρτύρησεν Ἰωάννης λέγων ὅτι Τεθέαμαι τὸ πνεῦμα καταβαῖνον ὡς περιστερὰν ἐξ οὐρανοῦ, καὶ ἔμεινεν ἐπ’ αὐτόν.', 'E testemunhou João dizendo que: Tenho contemplado o Espírito descendo como pomba do céu, e permaneceu sobre ele.', 'E João testemunhou: “Vi o Espírito descer do céu como pomba, e permaneceu sobre ele.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.32', 'Vi', 'Τεθέαμαι - *Tetheamai*', 'Verbo *theaomai* no perfeito do indicativo, indicando uma visão consciente, marcante e cujos efeitos continuam vivos e permanentes na memória da testemunha ocular.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.32', 'como pomba', 'ὡς περιστερὰν - *hōs peristeran*', 'Símbolo da ternura, pureza e da nova criação (ecoando o Espírito de Deus pairando sobre as águas em Gn 1:2 e a pomba de Noé trazendo o renovo da vida em Gn 8:11).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.32', 'permaneceu sobre ele', 'ἔμεινεν ἐπ’ αὐτόν - *emeinen ep’ auton*', 'O verbo *menō* ("permanecer", "habitar") é um conceito teológico basilar no Evangelho de João. Diferente dos profetas do AT sobre os quais o Espírito vinha transitoriamente para uma tarefa específica, sobre Jesus o Espírito Santo repousa de modo pleno, ininterrupto e eterno (cf. Is 11:2).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.33', 'JHN.1', 'JHN', 1, 33, 'κἀγὼ οὐκ ᾔδειν αὐτόν, ἀλλ’ ὁ πέμψας με βαπτίζειν ἐν ὕδατι ἐκεῖνός μοι εἶπεν· Ἐφ’ ὃν ἂν ἴδῃς τὸ πνεῦμα καταβαῖνον καὶ μένον ἐπ’ αὐτόν, οὗτός ἐστιν ὁ βαπτίζων ἐν πνεύματι ἁγίῳ.', 'E eu não o conhecia, mas o que me enviou a batizar em água aquele a mim disse: Sobre quem vires o Espírito descendo e permanecendo sobre ele, este é o que batiza em Espírito Santo.', 'Eu não o conhecia, mas aquele que me enviou a batizar com água me disse: ‘Aquele sobre quem você vir o Espírito descer e permanecer, esse é o que batiza no Espírito Santo’.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.33', 'DEUS', 74, 170, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.33', 'o que batiza no Espírito Santo', 'ὁ βαπτίζων ἐν πνεύματι ἁγίῳ - *ho baptizōn en pneumati hagiō*', 'Cumprimento das grandes promessas escatológicas dos profetas de que Deus derramaria o Seu próprio Espírito sobre toda a carne nos dias do Messias (cf. Ez 36:26-27; Jl 2:28). Jesus não apenas possui o Espírito, Ele é o doador soberano do Espírito.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.34', 'JHN.1', 'JHN', 1, 34, 'κἀγὼ ἑώρακα, καὶ μεμαρτύρηκα ὅτι οὗτός ἐστιν ὁ υἱὸς τοῦ θεοῦ.', 'E eu tenho visto, e tenho testemunhado que este é o Filho do Deus.', 'E eu vi e testemunhei que este é o Filho de Deus”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.34', 'Eu vi e dou testemunho', 'ἑώρακα καὶ μεμαρτύρηκα - *heōraka kai memartyrēka*', 'Ambos os verbos estão no tempo perfeito grego (*perfectum*), destacando uma experiência ocular consumada no passado com validade e autoridade jurídica perpétua no presente.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.34', 'o Filho de Deus', 'ὁ υἱὸς τοῦ θεοῦ - *ho huios tou theou*', 'O clímax do testemunho de João Batista, afirmando a filiação divina singular, messiânica e ontológica de Jesus.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.35', 'JHN.1', 'JHN', 1, 35, 'Τῇ ἐπαύριον πάλιν εἱστήκει ὁ Ἰωάννης καὶ ἐκ τῶν μαθητῶν αὐτοῦ δύο,', 'No dia seguinte outra vez estava em pé o João e dentre os discípulos dele dois,', 'No dia seguinte, João estava ali outra vez, com dois dos seus discípulos.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.35', 'dois dos seus discípulos', 'ἐκ τῶν μαθητῶν αὐτοῦ δύο - *ek tōn mathētōn autou dyo*', 'Um deles é explicitamente identificado no v. 40 como André, irmão de Pedro; o outro discípulo não nomeado é tradicionalmente entendido como o próprio apóstolo João, o autor do Evangelho.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.36', 'JHN.1', 'JHN', 1, 36, 'καὶ ἐμβλέψας τῷ Ἰησοῦ περιπατοῦντι λέγει· Ἴδε ὁ ἀμνὸς τοῦ θεοῦ.', 'E fitando os olhos no Jesus caminhando diz: Eis o cordeiro do Deus.', 'E, fixando o olhar em Jesus, que passava, disse: “Eis o Cordeiro de Deus!”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.36', 'Fixando o olhar', 'ἐμβλέψας - *emblepsas*', 'Particípio aoristo do verbo *emblepō*, que denota um olhar penetrante, focado, contemplativo e intencional.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.37', 'JHN.1', 'JHN', 1, 37, 'καὶ ἤκουσαν οἱ δύο μαθηταὶ αὐτοῦ λαλοῦντος καὶ ἠκολούθησαν τῷ Ἰησοῦ.', 'E ouviram os dois discípulos a ele falando e seguiram o Jesus.', 'Os dois discípulos o ouviram falar e seguiram Jesus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.37', 'seguiram Jesus', 'ἠκολούθησαν τῷ Ἰησοῦ - *ēkolouthēsan tō Iēsou*', 'O verbo *akoloutheō* ("seguir") tem peso de discipulado comprometido e dedicação de vida, e não mera locomoção física atrás de alguém. O objetivo máximo de João Batista é cumprido: transferir seus próprios discípulos para o Mestre Supremo.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.38', 'JHN.1', 'JHN', 1, 38, 'στραφεὶς δὲ ὁ Ἰησοῦς καὶ θεασάμενος αὐτοὺς ἀκολουθοῦντας λέγει αὐτοῖς· Τί ζητεῖτε; οἱ δὲ εἶπαν αὐτῷ· Ῥαββί (ὃ λέγεται μεθερμηνευόμενον Διδάσκαλε), ποῦ μένεις;', 'Voltando-se porém o Jesus e contemplando eles seguindo diz a eles: Que buscais? Eles porém disseram a ele: Rabi (que é dito sendo traduzido Mestre), onde permaneces?', 'Jesus voltou-se e, vendo que o seguiam, disse-lhes: “O que vocês procuram?”. Eles lhe disseram: “Rabi” — que quer dizer Mestre —, “onde você está hospedado?”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.38', 'JESUS', 53, 74, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.38', 'O que vocês procuram?', 'Τί ζητεῖτε - *Ti zēteite*', 'As primeiras palavras pronunciadas por Jesus no Evangelho de João constituem uma pergunta existencial profunda que desafia as motivações íntimas do coração de quem busca a Deus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.38', 'Rabi... onde você está hospedado?', 'Ῥαββί ... ποῦ μένεις - *Rhabbi ... pou meneis*', '*Rhabbi* (termo hebraico/aramaico de honra para mestres da Torá). A pergunta pelo "permanecer" (*menō*) vai além da curiosidade sobre endereço físico; revela o anseio de convívio contínuo e intimidade com o Mestre.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.39', 'JHN.1', 'JHN', 1, 39, 'λέγει αὐτοῖς· Ἔρχεσθε καὶ ὄψεσθε. ἦλθαν οὖν καὶ εἶδαν ποῦ μένει, καὶ παρ’ αὐτῷ ἔμειναν τὴν ἡμέραν ἐκείνην· ὥρα ἦν ὡς δεκάτη.', 'Diz a eles: Vinde e vereis. Foram então e viram onde permanece, e junto dele permaneceram o dia aquele; hora era cerca de décima.', 'Ele lhes disse: “Venham e vejam”. Foram, viram onde ele estava hospedado e ficaram com ele aquele dia. Era por volta das quatro da tarde.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.39', 'JESUS', 17, 31, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.39', 'Venham e vejam', 'Ἔρχεσθε καὶ ὄψεσθε - *Erchesthe kai opsesthe*', 'O convite essencial do cristianismo joanino não é uma adesão a um sistema filosófico abstrato, mas uma experiência direta e relacional com a pessoa de Cristo.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.39', 'hora décima', 'ὥρα ἦν ὡς δεκάτη - *hōra ēn hōs dekatē*', 'Pelo cômputo judaico (que contava as 12 horas do dia a partir do nascer do sol, por volta das 6h da manhã), a hora décima correspondia às 16h (quatro da tarde). A precisão do detalhe temporal reforça a lembrança vívida do autor como testemunha ocular daquele encontro inesquecível.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.40', 'JHN.1', 'JHN', 1, 40, 'Ἦν Ἀνδρέας ὁ ἀδελφὸς Σίμωνος Πέτρου εἷς ἐκ τῶν δύο τῶν ἀκουσάντων παρὰ Ἰωάννου καὶ ἀκολουθησάντων αὐτῷ·', 'Era André o irmão de Simão Pedro um dentre os dois dos que ouviram da parte de João e seguiram a ele;', 'André, irmão de Simão Pedro, era um dos dois que tinham ouvido João e seguido Jesus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.40', 'André', 'Ἀνδρέας - *Andreas*', 'Nome de origem grega (significando "varonil" ou "corajoso"), refletindo o ambiente cultural bilingue da Galileia gentílica. Em todas as suas aparições no Quarto Evangelho, André se destaca por conduzir outras pessoas a Jesus (cf. Jo 6:8-9; 12:20-22).', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.41', 'JHN.1', 'JHN', 1, 41, 'εὑρίσκει οὗτος πρῶτον τὸν ἀδελφὸν τὸν ἴδιον Σίμωνα καὶ λέγει αὐτῷ· Εὑρήκαμεν τὸν Μεσσίαν (ὅ ἐστιν μεθερμηνευόμενον Χριστός)·', 'Encontra este primeiro o irmão o próprio Simão e diz a ele: Encontramos o Messias (que é sendo traduzido Cristo);', 'Ele encontrou primeiro o seu irmão Simão e lhe disse: “Encontramos o Messias!” — que quer dizer Cristo.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.41', 'Encontramos o Messias', 'Εὑρήκαμεν τὸν Μεσσίαν - *Heurēkamen ton Messian*', '*Messias* é a transliteração grega direta do hebraico *Mashiach* ("o Ungido"), ocorrendo apenas aqui e em João 4:25 em todo o Novo Testamento. O narrador traduz para seus leitores de fala grega como *Christos*.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.42', 'JHN.1', 'JHN', 1, 42, 'ἤγαγεν αὐτὸν πρὸς τὸν Ἰησοῦν. ἐμβλέψας αὐτῷ ὁ Ἰησοῦς εἶπεν· Σὺ εἶ Σίμων ὁ υἱὸς Ἰωάννου, σὺ κληθήσῃ Κηφᾶς (ὃ ἑρμηνεύεται Πέτρος).', 'Conduziu ele para o Jesus. Fitando os olhos nele o Jesus disse: Tu és Simão o filho de João, tu serás chamado Cefas (que é interpretado Pedro).', 'E o levou a Jesus. Jesus fixou o olhar nele e disse: “Você é Simão, filho de João; você será chamado Cefas” — que quer dizer Pedro.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.42', 'JESUS', 54, 106, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.42', 'Cefas... Pedro', 'Κηφᾶς ... Πέτρος - *Kēphas ... Petros*', '*Kêfâ* é o termo aramaico para "rocha" ou "pedra", traduzido para o grego como *Petros*. A mudança de nome na cultura semítica denota uma transformação de identidade, vocação e destino conferida soberanamente por Deus (como Abrão para Abraão, Jacó para Israel).', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.43', 'JHN.1', 'JHN', 1, 43, 'Τῇ ἐπαύριον ἠθέλησεν ἐξελθεῖν εἰς τὴν Γαλιλαίαν, καὶ εὑρίσκει Φίλιππον. καὶ λέγει αὐτῷ ὁ Ἰησοῦς· Ἀκολούθει μοι.', 'No dia seguinte quis sair para a Galileia, e encontra Filipe. E diz a ele o Jesus: Segue-me.', 'No dia seguinte, Jesus resolveu partir para a Galileia. Encontrou Filipe e lhe disse: “Siga-me”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.43', 'JESUS', 87, 94, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.43', 'Siga-me', 'Ἀκολούθει μοι - *Akolouthei moi*', 'Imperativo presente ativo, demandando uma decisão contínua, ativa e incondicional de lealdade e caminhada em comunhão com o Mestre.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.44', 'JHN.1', 'JHN', 1, 44, 'ἦν δὲ ὁ Φίλιππος ἀπὸ Βηθσαϊδά, ἐκ τῆς πόλεως Ἀνδρέου καὶ Πέτρου.', 'Era porém o Filipe de Betsaida, da cidade de André e Pedro.', 'Filipe era de Betsaida, a cidade de André e de Pedro.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.44', 'Betsaida', 'Βηθσαϊδά - *Bēthsaida*', 'Do aramaico *Bet-Tsaida* ("Casa da Pesca"), vila de pescadores situada na margem norte do Mar da Galileia.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.45', 'JHN.1', 'JHN', 1, 45, 'εὑρίσκει Φίλιππος τὸν Ναθαναὴλ καὶ λέγει αὐτῷ· Ὃν ἔγραψεν Μωϋσῆς ἐν τῷ νόμῳ καὶ οἱ προφῆται εὑρήκαμεν, Ἰησοῦν υἱὸν τοῦ Ἰωσὴφ τὸν ἀπὸ Ναζαρέτ.', 'Encontra Filipe o Natanael e diz a ele: Aquele de quem escreveu Moisés na lei e os profetas encontramos, Jesus filho do José o de Nazaré.', 'Filipe encontrou Natanael e lhe disse: “Encontramos aquele de quem Moisés escreveu na Lei, e também os profetas: Jesus de Nazaré, o filho de José”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.45', 'Natanael', 'Ναθαναὴλ - *Nathanaēl*', 'Significa em hebraico "Presente de Deus" ou "Deus deu". Identificado comumente com o apóstolo Bartolomeu ("filho de Tolmai") nos evangelhos sinóticos.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.45', 'Moisés na Lei e os profetas', 'Μωϋσῆς ἐν τῷ νόμῳ καὶ οἱ προφῆται - *Mōusēs en tō nomō kai hoi prophētai*', 'A designação judaica clássica das Escrituras Hebraicas (o *Tanakh*), enfatizando que Jesus é a consumação de todo o cânon sagrado.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.46', 'JHN.1', 'JHN', 1, 46, 'καὶ εἶπεν αὐτῷ Ναθαναήλ· Ἐκ Ναζαρὲτ δύναταί τι ἀγαθὸν εἶναι; λέγει αὐτῷ [ὁ] Φίλιππος· Ἔρχου καὶ ἴδε.', 'E disse a ele Natanael: De Nazaré pode alguma coisa boa ser? Diz a ele o Filipe: Vem e vê.', 'Natanael lhe disse: “De Nazaré pode sair alguma coisa boa?”. Filipe lhe respondeu: “Venha e veja”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.46', 'De Nazaré pode sair algo de bom?', 'Ἐκ Ναζαρὲτ δύναταί τι ἀγαθὸν εἶναι - *Ek Nazaret dynatai ti agathon einai*', 'Nazaré era uma pequena e humilde aldeia galileia sem menção no Antigo Testamento nem no Talmude, e Natanael (sendo de Caná da Galileia, cf. Jo 21:2) expressava a rivalidade e o desdém regional comum da época.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.46', 'Venha e veja', 'Ἔρχου καὶ ἴδε - *Erchou kai ide*', 'Filipe repete o método de Jesus (v. 39), demonstrando que o ceticismo intelectual é superado pelo encontro existencial com Cristo.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.47', 'JHN.1', 'JHN', 1, 47, 'εἶδεν ὁ Ἰησοῦς τὸν Ναθαναὴλ ἐρχόμενον πρὸς αὐτὸν καὶ λέγει περὶ αὐτοῦ· Ἴδε ἀληθῶς Ἰσραηλίτης ἐν ᾧ δόλος οὐκ ἔστιν.', 'Viu o Jesus o Natanael vindo para ele e diz acerca dele: Eis verdadeiramente um israelita em quem engano não há.', 'Jesus viu Natanael vindo em sua direção e disse a seu respeito: “Eis um verdadeiro israelita, em quem não há engano!”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.47', 'JESUS', 65, 116, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.47', 'um verdadeiro israelita em quem não há engano', 'ἀληθῶς Ἰσραηλίτης ἐν ᾧ δόλος οὐκ ἔστιν - *alēthōs Israēlitēs en hō dolos ouk estin*', 'Alusão ao patriarca Jacó (que deu origem a Israel), conhecido originalmente por sua astúcia e engano (*dolos*, ao enganar seu pai Isaque para obter a bênção em Gn 27:35). Jesus saúda Natanael como um homem íntegro e sincero que personifica o verdadeiro Israel sem duplicidade de espírito.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.48', 'JHN.1', 'JHN', 1, 48, 'λέγει αὐτῷ Ναθαναήλ· Πόθεν με γινώσκεις; ἀπεκρίθη Ἰησοῦς καὶ εἶπεν αὐτῷ· Πρὸ τοῦ σε Φίλιππον φωνῆσαι ὄντα ὑπὸ τὴν συκῆν εἶδόν σε.', 'Diz a ele Natanael: De onde me conheces? Respondeu Jesus e disse a ele: Antes de o Filipe te chamar, estando sob a figueira, vi-te.', 'Natanael lhe perguntou: “De onde você me conhece?”. Jesus respondeu: “Antes que Filipe o chamasse, quando você estava debaixo da figueira, eu o vi”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.48', 'JESUS', 70, 146, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.48', 'debaixo da figueira', 'ὑπὸ τὴν συκῆν - *hypo tēn sykēn*', 'Na literatura rabínica, estar "debaixo da figueira" era uma expressão idiomática e prática devocional comum para o estudo e a meditação piedosa das Escrituras e da Lei (*Torá*), além de símbolo profético de paz e segurança messiânica (cf. Mq 4:4; Zc 3:10). A onisciência sobrenatural de Jesus penetrou o santuário secreto de oração de Natanael.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.49', 'JHN.1', 'JHN', 1, 49, 'ἀπεκρίθη αὐτῷ Ναθαναήλ· Ῥαββί, σὺ εἶ ὁ υἱὸς τοῦ θεοῦ, σὺ βασιλεὺς εἶ τοῦ Ἰσραήλ.', 'Respondeu a ele Natanael: Rabi, tu és o Filho do Deus, tu Rei és do Israel.', 'Natanael lhe respondeu: “Rabi, você é o Filho de Deus! Você é o Rei de Israel!”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.49', 'Filho de Deus... Rei de Israel', 'ὁ υἱὸς τοῦ θεοῦ ... βασιλεὺς τοῦ Ἰσραήλ - *ho huios tou theou ... basileus tou Israēl*', 'Confissão messiânica pactual baseada no Salmo 2:6-7 ("Tu és meu Filho... ungir o meu Rei sobre Sião"). Natanael reconhece instantaneamente a dignidade régia e divina de Jesus.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.50', 'JHN.1', 'JHN', 1, 50, 'ἀπεκρίθη Ἰησοῦς καὶ εἶπεν αὐτῷ· Ὅτι εἶπόν σοι ὅτι εἶδόν σε ὑποκάτω τῆς συκῆς πιστεύεις; μείζω τούτων ὄψῃ.', 'Respondeu Jesus e disse a ele: Porque te disse que te vi debaixo da figueira crês? Coisas maiores do que estas verás.', 'Jesus lhe respondeu: “Você crê porque eu lhe disse que o vi debaixo da figueira? Você verá coisas maiores do que estas”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.50', 'JESUS', 22, 118, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.50', 'você verá coisas maiores do que estas', 'μείζω τούτων ὄψῃ - *meizō toutōn opsē*', 'Promessa que inaugura a progressão de revelações e milagres portentosos (*sēmeia*) que se desenrolarão ao longo do Evangelho.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.1.51', 'JHN.1', 'JHN', 1, 51, 'καὶ λέγει αὐτῷ· Ἀμὴν ἀμὴν λέγω ὑμῖν, ὄψεσθε τὸν οὐρανὸν ἀνεῳγότα καὶ τοὺς ἀγγέλους τοῦ θεοῦ ἀναβαίνοντας καὶ καταβαίνοντας ἐπὶ τὸν υἱὸν τοῦ ἀνθρώπου.', 'E diz a ele: Em verdade em verdade vos digo, vereis o céu aberto e os anjos do Deus subindo e descendo sobre o Filho do homem.', 'E disse-lhe: “Em verdade, em verdade lhes digo: vocês verão o céu aberto e os anjos de Deus subindo e descendo sobre o Filho do Homem”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.1.51', 'JESUS', 14, 133, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.51', 'Em verdade, em verdade lhes digo', 'Ἀμὴν ἀμὴν λέγω ὑμῖν - *Amēn amēn legō hymin*', 'A fórmula do duplo *Amém* é exclusiva de Jesus no Evangelho de João (ocorre 25 vezes), introduzindo revelações de máxima solenidade e autoridade divina inquestionável. Note que o pronome passa para o plural (*hymin* - "a todos vocês"), ampliando a promessa a todos os discípulos.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.51', 'os anjos de Deus subindo e descendo', 'τοὺς ἀγγέλους τοῦ θεοῦ ἀναβαίνοντας καὶ καταβαίνοντας - *tous angelous tou theou anabainontas kai katabainontas*', 'Alusão direta à visão do patriarca Jacó em Betel (Gn 28:12 — a "Escada de Jacó"). Jesus declara que Ele próprio é a ponte viva e a escada cósmica que conecta definitivamente a Terra ao Céu, reconciliando a humanidade com Deus.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.1.51', 'o Filho do Homem', 'τὸν υἱὸν τοῦ ἀνθρώπου - *ton huion tou anthrōpou*', 'O título predileto de Jesus para Si mesmo, derivado da visão messiânica celestial de Daniel 7:13-14, associando Sua identidade à figura gloriosa, celestial e investida de autoridade eterna sobre todas as nações.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.1', 'JHN.2', 'JHN', 2, 1, 'Καὶ τῇ ἡμέρᾳ τῇ τρίτῃ γάμος ἐγένετο ἐν Κανὰ τῆς Γαλιλαίας, καὶ ἦν ἡ μήτηρ τοῦ Ἰησοῦ ἐκεῖ·', 'E no dia terceiro um casamento aconteceu em Caná da Galileia, e estava a mãe de Jesus lá;', 'No terceiro dia, houve um casamento em Caná da Galileia, e a mãe de Jesus estava lá.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.1', 'No terceiro dia', 'τῇ ἡμέρᾳ τῇ τρίτῃ - *tē hēmera tē tritē*', 'Dativo de tempo que conecta a narrativa à sequência cronológica inaugurada no capítulo 1 (1:29, 35, 43), totalizando o sétimo dia simbólico — uma semana inaugural que evoca a Criação em Gênesis. Ao mesmo tempo, "o terceiro dia" antecipa a tipologia da ressurreição (2:19; cf. Os 6:2).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.1', 'casamento', 'γάμος - *gamos*', 'No judaísmo do Segundo Templo, o banquete de casamento durava tipicamente sete dias (ou até quatorze), sendo a celebração comunitária mais solene da vida social e imagem profética clássica do banquete messiânico escatológico (Is 25:6; Ap 19:7-9).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.1', 'Caná da Galileia', 'Κανὰ τῆς Γαλιλαίας - *Kana tēs Galilaias*', 'Identificada hoje principalmente com *Khirbet Qana* (cerca de 14 km ao norte de Nazaré) ou *Kafr Kanna* (6 km a nordeste). A especificação "da Galileia" distinguia o vilarejo de outra Caná situada na Judeia.', 3);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.1', 'a mãe de Jesus', 'ἡ μήτηρ τοῦ Ἰησοῦ - *hē mētēr tou Iēsou*', 'O Quarto Evangelho nunca cita o nome pessoal "Maria" para a mãe de Jesus. Ela é apresentada consistentemente por sua função teológica e relacional ("a mãe de Jesus"), aparecendo apenas aqui no início do ministério público e no encerramento, junto à cruz (19:25-27).', 4);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.2', 'JHN.2', 'JHN', 2, 2, 'ἐκλήθη δὲ καὶ ὁ Ἰησοῦς καὶ οἱ μαθηταὶ αὐτοῦ εἰς τὸν γάμον.', 'Foi convidado porém também o Jesus e os discípulos dele para o casamento.', 'Jesus e seus discípulos também foram convidados para o casamento.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.2', 'foram convidados', 'ἐκλήθη - *eklēthē*', 'Verbo no aoristo passivo singular, concordando formalmente com o primeiro sujeito (*Jesus*), com a adição paratática dos discípulos. O convite provavelmente decorre de laços de parentesco ou proximidade da família de Jesus com os anfitriões em Caná (aldeia natal de Natanael, cf. Jo 21:2).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.2', 'seus discípulos', 'οἱ μαθηταὶ αὐτοῦ - *hoi mathētai autou*', 'Refere-se ao primeiro grupo recém-formado no capítulo 1 (André, Pedro, Filipe, Natanael e o outro discípulo). A presença dos discípulos marca a transição de Jesus de figura privada a mestre acompanhado por Sua comunidade.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.3', 'JHN.2', 'JHN', 2, 3, 'καὶ ὑστερήσαντος οἴνου λέγει ἡ μήτηρ τοῦ Ἰησοῦ πρὸς αὐτόν· Οἶνον οὐκ ἔχουσιν.', 'E tendo faltado vinho diz a mãe de Jesus para ele: Vinho não têm.', 'Quando o vinho acabou, a mãe de Jesus lhe disse: “Não têm vinho”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.3', 'Quando o vinho acabou', 'ὑστερήσαντος οἴνου - *hysterēsantos oinou*', 'Construção em genitivo absoluto com o particípio aoristo de *hystereō* ("faltar", "esgotar-se"). No ambiente de hospitalidade do Antigo Oriente Médio, o término do vinho em um banquete nupcial era uma vergonha social devastadora para a família dos noivos e podia acarretar até processos civis por quebra de obrigações comunitárias.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.3', 'Não têm vinho', 'Οἶνον οὐκ ἔχουσιν - *Oinon ouk echousin*', 'O substantivo *oinos* ("vinho") abre enfaticamente a declaração no grego. Nas Escrituras Hebraicas, o vinho abundante é o símbolo primordial da era messiânica, da alegria e da bênção pactual de Deus (Am 9:13; Jl 3:18; Jr 31:12). A escassez do vinho físico aponta simbolicamente para o esgotamento do sistema religioso e das instituições da Antiga Aliança.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.4', 'JHN.2', 'JHN', 2, 4, 'καὶ λέγει αὐτῇ ὁ Ἰησοῦς· Τί ἐμοὶ καὶ σοί, γύναι; οὔπω ἥκει ἡ ὥρα μου.', 'E diz a ela o Jesus: O que a mim e a ti, mulher? Ainda não chegou a hora de mim.', 'E Jesus lhe disse: “Que tenho eu com você, mulher? A minha hora ainda não chegou”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.2.4', 'JESUS', 20, 80, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.4', 'Que tenho eu com você', 'Τί ἐμοὶ καὶ σοί - *Ti emoi kai soi*', 'Semitismo idiomático clássico (hebraico *mah-llî vālāk*), atestado frequentemente no Antigo Testamento (Jz 11:12; 2Sm 16:10; 1Rs 17:18; 2Rs 3:13) e nos Evangelhos (Mt 8:29; Mc 1:24). A expressão delimita esferas de autoridade e interesse: Jesus não desrespeita sua mãe, mas esclarece que sua missão messiânica não se submete a laços de parentesco humano nem a expectativas terrenas, respondendo exclusivamente ao cronograma soberano do Pai.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.4', 'mulher', 'γύναι - *gynai*', 'Vocativo grego que, no contexto do primeiro século, era uma forma digna, respeitosa e afetuosa de tratamento público (cf. Augusto dirigindo-se a Cleópatra; Jesus à mulher samaritana em Jo 4:21 e a Maria Madalena em Jo 20:15). Não possui o tom rude ou depreciativo que o vocativo adquiriu em certas variedades do português moderno. Ao mesmo tempo, o uso de *gynai* em vez de "mãe" reconfigura a relação entre ambos: Jesus a interpela não como mero filho terreno, mas como o Messias e Redentor, ecoando a "mulher" da promessa protoevangélica (Gn 3:15; Jo 19:26).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.4', 'A minha hora ainda não chegou', 'οὔπω ἥκει ἡ ὥρα μου - *oupō hēkei hē hōra mou*', 'O tema teológico da "hora" (*hē hōra*) é central na arquitetura do Quarto Evangelho. Enquanto nos capítulos iniciais "a hora ainda não chegou" (cf. Jo 7:30; 8:20), em João 12:23 e 13:1 ela se consuma: a "hora" de Jesus é o momento supremo de Sua exaltação, que na teologia joanina é inseparável de Sua crucificação, morte, ressurreição e glorificação.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.5', 'JHN.2', 'JHN', 2, 5, 'λέγει ἡ μήτηρ αὐτοῦ τοῖς διακόνοις· Ὅ τι ἂν λέγῃ ὑμῖν ποιήσατε.', 'Diz a mãe dele aos servos: O que quer que diga a vós, fazei.', 'Sua mãe disse aos servos: “Façam tudo o que ele lhes disser”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.5', 'servos', 'τοῖς διακόνοις - *tois diakonois*', 'Termo grego para aqueles que servem às mesas e executam tarefas operacionais de apoio (origem da palavra "diácono"), distinguindo-se de escravos submetidos (*douloi*).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.5', 'Façam tudo o que ele lhes disser', 'Ὅ τι ἂν λέγῃ ὑμῖν ποιήσατε - *Ho ti an legē hymin poiēsate*', 'Cláusula condicional indefinida com o aoristo imperativo *poiēsate* ("fazei imediatamente"). A instrução de Maria ecoa a resposta do povo de Israel a Yahweh no Sinai (Êx 19:8; 24:3: "Tudo o que o Senhor falou, faremos") e a ordem de Faraó no Egito em relação a José (Gn 41:55: "Ide a José; o que ele vos disser, fazei"). Maria se coloca como modelo de submissão e fé, transferindo toda a autoridade decisória para a palavra de Jesus.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.6', 'JHN.2', 'JHN', 2, 6, 'ἦσαν δὲ ἐκεῖ λίθιναι ὑδρίαι ἓξ κατὰ τὸν καθαρισμὸν τῶν Ἰουδαίων κείμεναι, χωροῦσαι ἀνὰ μετρητὰς δύο ἢ τρεῖς.', 'Estavam porém lá de pedra talhas seis segundo a purificação dos judeus postas, contendo cada uma metretas duas ou três.', 'Havia ali seis talhas de pedra para a purificação dos judeus, cada uma com capacidade de oitenta a cento e vinte litros.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.6', 'talhas de pedra', 'λίθιναι ὑδρίαι - *lithinai hydriai*', 'Vasos talhados em calcário. Segundo a lei de pureza rabínica (*Halakhá*, tratada no tratado *Kelim* da Mishná), recipientes de cerâmica tornavam-se ritualmente impuros em caso de contato com matéria contaminada e deviam ser quebrados; os recipientes de pedra, contudo, eram imunes à transmissão de impureza ritual levítica, sendo fundamentais para a guarda da água de purificação.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.6', 'purificação dos judeus', 'τὸν καθαρισμὸν τῶν Ἰουδαίων - *ton katharismon tōn Ioudaiōn*', 'Rituais de ablução de mãos, pés e utensílios antes das refeições para remover impurezas cerimoniais (cf. Mc 7:3-4). Jesus utiliza justamente o instrumental da antiga purificação externa para manifestar a abundância da nova realidade espiritual.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.6', 'oitenta a cento e vinte litros', 'ἀνὰ μετρητὰς δύο ἢ τρεῖς - *ana metrētas dyo ē treis*', 'A metreta grega (*metrētēs*) correspondia ao *bat* hebraico, uma unidade volumétrica de cerca de 39 a 40 litros. "Duas ou três metretas" por talha equivale a uma capacidade individual de 80 a 120 litros. As seis talhas juntas somavam, portanto, entre 480 e 720 litros de água (convertidos integralmente em vinho de altíssima qualidade), enfatizando a prodigalidade messiânica esmagadora e irrefreável da graça de Deus.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.7', 'JHN.2', 'JHN', 2, 7, 'λέγει αὐτοῖς ὁ Ἰησοῦς· Γεμίσατε τὰς ὑδρίας ὕδατος· καὶ ἐγέμισαν αὐτὰς ἕως ἄνω.', 'Diz a eles o Jesus: Enchei as talhas de água. E encheram elas até acima.', 'Jesus lhes disse: “Encham as talhas de água”. E eles as encheram até a borda.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.2.7', 'JESUS', 19, 43, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.7', 'Encham as talhas', 'Γεμίσατε τὰς ὑδρίας - *Gemisate tas hydrias*', 'Imperativo aoristo ativo de *gemizō*, exigindo ação completa e imediata.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.7', 'até a borda', 'ἕως ἄνω - *heōs anō*', 'Literalmente "até em cima / até o topo". O detalhe atesta a realidade física do sinal: não havia espaço para qualquer adição humana ou mistura de substâncias no interior dos vasos. O milagre ocorre pela palavra criadora de Cristo operando sobre a totalidade do elemento original.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.8', 'JHN.2', 'JHN', 2, 8, 'καὶ λέγει αὐτοῖς· Ἀντλήσατε νῦν καὶ φέρετε τῷ ἀρχιτρικλίνῳ· οἱ δὲ ἤνεγκαν.', 'E diz a eles: Tirai agora e levai ao mestre de cerimônias; eles porém levaram.', 'E lhes disse: “Tirem agora e levem ao mestre de cerimônias”. E eles levaram.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.2.8', 'JESUS', 15, 58, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.8', 'Tirem agora', 'Ἀντλήσατε νῦν - *Antlēsate nyn*', 'O verbo *antleō* significa retirar líquido de um poço ou de um vaso profundo com um jarro de serviço. O advérbio temporal *nyn* ("agora") marca a passagem instantânea da ordem ao cumprimento milagroso.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.8', 'mestre de cerimônias', 'τῷ ἀρχιτρικλίνῳ - *tō architriklinō*', 'Composto helenístico formado por *archōn* ("líder/diretor") e *triklinion* ("triclínio", o arranjo de três divãs em formato de ''U'' típico das salas de banquete greco-romanas). Designava o organizador do banquete (frequentemente um amigo íntimo da família ou profissional contratado) responsável pela disposição dos assentos, controle do serviço das mesas e inspeção da qualidade dos alimentos e bebidas servidos aos convidados.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.9', 'JHN.2', 'JHN', 2, 9, 'ὡς δὲ ἐγεύσατο ὁ ἀρχιτρίκλινος τὸ ὕδωρ οἶνον γεγενημένον, καὶ οὐκ ᾔδει πόθεν ἐστίν, οἱ δὲ διάκονοι ᾔδεισαν οἱ ἠντληκότες τὸ ὕδωρ, φωνεῖ τὸν νυμφίον ὁ ἀρχιτρίκλινος', 'Como porém provou o mestre de cerimônias a água vinho tornada, e não sabia de onde é, os porém servos sabiam, os que tinham tirado a água, chama o noivo o mestre de cerimônias', 'Quando o mestre de cerimônias provou a água tornada vinho — e não sabia de onde vinha, mas os servos que tinham tirado a água sabiam —, chamou o noivo');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.9', 'água tornada vinho', 'τὸ ὕδωρ οἶνον γεγενημένον - *to hydōr oinon gegēnēmenon*', 'Particípio perfeito passivo do verbo *ginomai* ("tornar-se", "vir a ser"), indicando que a transformação ontológica da substância já se completara perfeitamente no momento da degustação.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.9', 'não sabia... mas os servos... sabiam', 'οὐκ ᾔδει ... οἱ δὲ διάκονοι ᾔδεισαν - *ouk ēdei ... hoi de diakonoi ēdeisan*', 'Ironia dramática tipicamente joanina: as autoridades e os mestres humanos ignoram a origem da graça divina, enquanto os servos obedientes e subalternos tornam-se testemunhas e depositários da revelação dos mistérios de Deus.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.9', 'de onde vinha', 'πόθεν ἐστίν - *pothen estin*', 'A pergunta pela origem (*pothen*, "de onde?") é um dos motivos recorrentes no Evangelho de João para interrogar a autoridade celeste e a identidade transcendente de Jesus (cf. 3:8; 4:11; 7:27-28; 8:14; 9:29-30; 19:9).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.10', 'JHN.2', 'JHN', 2, 10, 'καὶ λέγει αὐτῷ· Πᾶς ἄνθρωπος πρῶτον τὸν καλὸν οἶνον τίθησιν, καὶ ὅταν μεθυσθῶσιν τὸν ἐλάσσω· σὺ τετήρηκας τὸν καλὸν οἶνον ἕως ἄρτι.', 'E diz a ele: Todo homem primeiro o bom vinho serve, e quando tiverem bebido fartamente, o inferior; tu guardaste o bom vinho até agora.', 'e lhe disse: “Todo homem serve primeiro o bom vinho e, quando já estão embriagados, o inferior; você guardou o bom vinho até agora”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.10', 'o bom vinho', 'τὸν καλὸν οἶνον - *ton kalon oinon*', 'O adjetivo *kalos* exprime não apenas excelência estética ou gustativa, mas pureza moral, nobreza e perfeição intrínseca. Jesus não produz uma bebida medíocre para suprir uma emergência; Ele fornece o melhor vinho possível, símbolo da plenitude e da glória da Nova Aliança.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.10', 'quando já estão embriagados', 'ὅταν μεθυσθῶσιν - *hotan methysthōsin*', 'Subjuntivo aoristo passivo de *methyskō* ("embriagar-se", "beber abundantemente até a saciedade"), quando o paladar dos convivas já perdeu a capacidade de discernir sutilezas de sabor e qualidade.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.10', 'você guardou o bom vinho até agora', 'σὺ τετήρηκας τὸν καλὸν οἶνον ἕως ἄρτι - *sy tetērēkas ton kalon oinon heōs arti*', 'O pronome enfático *sy* ("você") confronta o noivo, atribuindo-lhe a surpresa da inversão do costume social. Teologicamente, Deus reservou a revelação suprema da graça salvadora para os últimos tempos: a Antiga Aliança foi sucedida pela Nova, que é incomparavelmente superior (cf. Hb 1:1-2; Jo 1:16-17).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.11', 'JHN.2', 'JHN', 2, 11, 'ταύτην ἐποίησεν ἀρχὴν τῶν σημείων ὁ Ἰησοῦς ἐν Κανὰ τῆς Γαλιλαίας καὶ ἐφανέρωσεν τὴν δόξαν αὐτοῦ, καὶ ἐπίστευσαν εἰς αὐτὸν οἱ μαθηταὶ αὐτοῦ.', 'Este fez princípio dos sinais o Jesus em Caná da Galileia e manifestou a glória dele, e creram nele os discípulos dele.', 'Jesus realizou este primeiro dos seus sinais em Caná da Galileia e manifestou a sua glória; e os seus discípulos creram nele.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.11', 'primeiro dos seus sinais', 'ἀρχὴν τῶν σημείων - *archēn tōn sēmeiōn*', 'João evita deliberadamente os termos sinóticos usuais para milagres — como *dynamis* ("ato de poder / prodígio") e *teras* ("portento espantoso") —, preferindo sistematicamente *sēmeion* ("sinal"). Para João, os milagres de Jesus não são exibições espetaculares de magia, mas placas indicadoras que apontam para além de si mesmas, revelando a identidade divina, messiânica e teológica de Jesus. O Quarto Evangelho é estruturado em torno de sete sinais messiânicos específicos.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.11', 'manifestou a sua glória', 'ἐφανέρωσεν τὴν δόξαν αὐτοῦ - *ephanerōsen tēn doxan autou*', 'Cumprimento do prólogo ("vimos a sua glória", Jo 1:14). A glória (*doxa* / hebraico *Kavod*) de Cristo, velada em Sua humanidade, irrompe visivelmente na transformação criadora dos elementos da criação.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.11', 'creram nele os seus discípulos', 'ἐπίστευσαν εἰς αὐτὸν οἱ μαθηταὶ αὐτοῦ - *episteusan eis auton hoi mathētai autou*', 'A construção *pisteuō eis* com acusativo expressa entrega pessoal, confiança dinâmica e adesão existencial permanente à pessoa de Jesus, transcendendo o mero consentimento intelectual de dados históricos.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.12', 'JHN.2', 'JHN', 2, 12, 'Μετὰ τοῦτο κατέβη εἰς Καφαρναοὺμ αὐτὸς καὶ ἡ μήτηρ αὐτοῦ καὶ οἱ ἀδελφοὶ καὶ οἱ μαθηταὶ αὐτοῦ, καὶ ἐκεῖ ἔμειναν οὐ πολλὰς ἡμέρας.', 'Depois disto desceu para Cafarnaum ele e a mãe dele e os irmãos e os discípulos dele, e lá permaneceram não muitos dias.', 'Depois disso, ele desceu para Cafarnaum, com sua mãe, seus irmãos e seus discípulos; e ficaram lá não muitos dias.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.12', 'desceu para Cafarnaum', 'κατέβη εἰς Καφαρναοὺμ - *katebē eis Kapharnaoum*', 'A expressão "desceu" reflete a topografia precisa da Galileia: Caná ficava nas colinas mais elevadas (cerca de 200 a 300 metros acima do nível do mar), enquanto Cafarnaum situava-se às margens do Mar da Galileia, a mais de 200 metros abaixo do nível do mar. Cafarnaum viria a se tornar a base das operações missionárias de Jesus no norte.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.12', 'seus irmãos', 'οἱ ἀδελφοὶ - *hoi adelphoi*', 'Refere-se aos irmãos de Jesus (Tiago, José, Simão e Judas, cf. Mt 13:55; Mc 6:3). Em João 7:5, o evangelista nota que, nesta fase inicial, eles ainda não criam plenamente n’Ele, embora o acompanhassem em viagens familiares.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.12', 'não muitos dias', 'οὐ πολλὰς ἡμέρας - *ou pollas hēmeras*', 'Literalmente "não muitos dias" (litote grega), indicando uma estada breve e transitória antes da subida a Jerusalém para a festa pascal.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.13', 'JHN.2', 'JHN', 2, 13, 'Καὶ ἐγγὺς ἦν τὸ πάσχα τῶν Ἰουδαίων, καὶ ἀνέβη εἰς Ἱεροσόλυμα ὁ Ἰησοῦς.', 'E perto estava a páscoa dos judeus, e subiu para Jerusalém o Jesus.', 'Estava próxima a Páscoa dos judeus, e Jesus subiu a Jerusalém.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.13', 'Páscoa dos judeus', 'τὸ πάσχα τῶν Ἰουδαίων - *to pascha tōn Ioudaiōn*', 'A principal festa do calendário litúrgico bíblico (Êxodo 12; Levítico 23:5), celebrando a libertação do Egito pela aspersão do sangue do cordeiro. O Evangelho de João é o único que estrutura a cronologia do ministério de Jesus em torno de três celebrações da Páscoa (2:13; 6:4; 11:55/12:1), atestando a duração de aproximadamente três anos de ministério público.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.13', 'subiu a Jerusalém', 'ἀνέβη εἰς Ἱεροσόλυμα - *anebē eis Hierosolyma*', 'O verbo *anabainō* ("subir") é usado tanto pela elevação geográfica de Jerusalém (situada a cerca de 750 metros de altitude nas montanhas da Judeia) quanto pela tradição teológica dos Salmos de Romagem ou Peregrinação (*Salmos de Degraus / Ma''alot*, Sl 120–134).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.14', 'JHN.2', 'JHN', 2, 14, 'καὶ εὗρεν ἐν τῷ ἱερῷ τοὺς πωλοῦντας βόας καὶ πρόβατα καὶ περιστερὰς καὶ τοὺς κερματιστὰς καθημένους,', 'E encontrou no templo os que vendiam bois e ovelhas e pombas e os cambistas sentados,', 'E encontrou no Templo os que vendiam bois, ovelhas e pombas, e os cambistas sentados.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.14', 'no Templo', 'ἐν τῷ ἱερῷ - *en tō hierō*', 'O grego distingue rigorosamente *hieron* (o complexo arquitetônico total do Templo, incluindo as colunatas, pátios externos e o Pátio dos Gentios) de *naos* (o santuário interior, compreendendo o Santo Lugar e o Santo dos Santos, reservado aos sacerdotes). O comércio ocorria no vasto Pátio dos Gentios — o único local do Templo onde os não-judeus podiam orar —, transformado em feira ruidosa e excludente pela administração sacerdotal saduceia.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.14', 'bois, ovelhas e pombas', 'βόας καὶ πρόβατα καὶ περιστεράς - *boas kai probata kai peristeras*', 'Animais prescritos pela Lei para sacrifícios levíticos de expiação e comunhão (Lv 1–5). As pombas constituíam a oferta permitida aos mais pobres que não possuíam recursos para adquirir gado miúdo (Lv 5:7; 12:8; Lc 2:24).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.14', 'cambistas', 'τοὺς κερματιστάς - *tous kermatistas*', 'Trocadores de dinheiro (de *kermatizō*, "trocar moedas pequenas"). Todo homem judeu a partir dos vinte anos era obrigado a pagar anualmente o imposto de meio siclo para a manutenção do Templo (Êx 30:13-16). Como moedas gregas e romanas com efígies pagãs de imperadores e deuses eram consideradas idólatras, os cambistas faziam o câmbio compulsório para o siclo de Tiro, cobrando taxas extorsivas autorizadas pelas famílias do sumo sacerdote.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.15', 'JHN.2', 'JHN', 2, 15, 'καὶ ποιήσας φραγέλλιον ἐκ σχοινίων πάντας ἐξέβαλεν ἐκ τοῦ ἱεροῦ τά τε πρόβατα καὶ τοὺς βόας, καὶ τῶν κολλυβιστῶν ἐξέχεεν τὰ κέρματα καὶ τὰς τραπέζας ἀνέστρεψεν,', 'E tendo feito um chicote de cordas todos expulsou do templo, tanto as ovelhas quanto os bois, e dos cambistas derramou as moedas e as mesas virou,', 'E, fazendo um chicote de cordas, expulsou todos do Templo, tanto as ovelhas como os bois; derramou as moedas dos cambistas e virou as suas mesas.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.15', 'chicote de cordas', 'φραγέλλιον ἐκ σχοινίων - *phragellion ek schoinion*', 'O substantivo *phragellion* (empréstimo do latim *flagellum*) indica um chicote improvisado com as cordas de junco ou feno utilizadas para atar o gado nos estábulos do Templo. Jesus confecciona o instrumento deliberadamente, agindo não por fúria descontrolada, mas com autoridade régia e profética para restaurar a santidade do espaço cúltico.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.15', 'expulsou todos do Templo', 'πάντας ἐξέβαλεν ἐκ τοῦ ἱεροῦ - *pantas exebalen ek tou hierou*', 'O verbo *ekballō* expressa expulsão enérgica e irrecorrível. A construção gramatical *pantas ... ta te probata kai tous boas* abrange tanto os comerciantes desonestos quanto seus rebanhos.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.15', 'derramou as moedas dos cambistas e virou as suas mesas', 'τῶν κολλυβιστῶν ἐξέχεεν τὰ κέρματα καὶ τὰς τραπέζας ἀνέστρεψεν - *tōn kollybistōn execheen ta kermata kai tas trapezas anestrepsen*', 'Ação profética contundente que interrompe instantaneamente a operação financeira do Templo, prenunciando a cessação do culto sacrificial levítico e o juízo divino sobre o sacerdócio corrompido (cf. Jr 7:11).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.16', 'JHN.2', 'JHN', 2, 16, 'καὶ τοῖς τὰς περιστερὰς πωλοῦσιν εἶπεν· Ἄρατε ταῦτα ἐντεῦθεν, μὴ ποιεῖτε τὸν οἶκον τοῦ πατρός μου οἶκον ἐμπορίου.', 'E aos as pombas vendendo disse: Tirai estas coisas daqui; não façais a casa do pai meu casa de comércio.', 'E disse aos que vendiam pombas: “Tirem estas coisas daqui! Não façam da casa de meu Pai uma casa de comércio!”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.2.16', 'JESUS', 33, 109, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.16', 'casa de meu Pai', 'τὸν οἶκον τοῦ πατρός μου - *ton oikon tou patros mou*', 'Jesus reivindica filiação divina singular e autoridade filial sobre o santuário de Jerusalém. Ao chamá-lo de "casa de *meu* Pai" (em contraste com o genérico "casa de nosso Pai"), Ele atua como o Filho primogênito e herdeiro soberano que põe em ordem a Sua própria morada familiar (cf. Lc 2:49; Hb 3:6).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.16', 'casa de comércio', 'οἶκον ἐμπορίου - *oikon emporiou*', 'Alusão direta à profecia de Zacarias 14:21 ("naquele dia não haverá mais mercador na casa do Senhor dos Exércitos"). A liderança religiosa subordinara a adoração e o acesso dos gentios e dos pobres ao lucro monetário mercantilista.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.17', 'JHN.2', 'JHN', 2, 17, 'ἐμνήσθησαν οἱ μαθηταὶ αὐτοῦ ὅτι γεγραμμένον ἐστίν· Ὁ ζῆλος τοῦ οἴκου σου καταφάγεταί με.', 'Lembraram-se os discípulos dele que escrito está: O zelo da casa tua me devorará.', 'Os seus discípulos lembraram-se de que está escrito: “O zelo pela tua casa me consumirá”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.2.17', 'ESCRITURA', 54, 87, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.17', 'está escrito', 'γεγραμμένον ἐστίν - *gegrammenon estin*', 'Perfeito passivo indicativo de *graphō*, fórmula rabínica padrão para declarar a autoridade permanente e inabalável das Escrituras divinamente inspiradas.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.17', 'O zelo pela tua casa me consumirá', 'Ὁ ζῆλος τοῦ οἴκου σου καταφάγεταί με - *Ho zēlos tou oikou sou kataphagetai me*', 'Citação exata do Salmo 69:9 (Sl 68:10 LXX). Enquanto o texto hebraico traz o verbo no perfeito ("me consumiu"), o texto grego dos manuscritos de João traz o verbo no futuro indicativo (*kataphagetai*, "me consumirá / me devorará"), conferindo-lhe uma dimensão profética direta: o zelo incandescente de Jesus pela santidade de Deus e de Seu culto seria a causa direta de Sua rejeição pelas autoridades e de Sua morte na cruz.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.18', 'JHN.2', 'JHN', 2, 18, 'ἀπεκρίθησαν οὖν οἱ Ἰουδαῖοι καὶ εἶπαν αὐτῷ· Τί σημεῖον δεικνύεις ἡμῖν, ὅτι ταῦτα ποιεῖς;', 'Responderam então os judeus e disseram a ele: Que sinal mostras a nós, visto que estas coisas fazes?', 'As autoridades judaicas então lhe perguntaram: “Que sinal você nos mostra, já que faz estas coisas?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.18', 'As autoridades judaicas', 'οἱ Ἰουδαῖοι - *hoi Ioudaioi*', 'No vocabulário do Evangelho de João, *hoi Ioudaioi* não designa o povo de Israel indistintamente em sentido étnico (uma vez que Jesus, os apóstolos e os primeiros crentes eram todos judeus), mas especificamente a liderança religiosa e aristocrática sediada em Jerusalém (os sacerdotes, o Sinédrio e os fariseus) que se opunha à revelação messiânica de Jesus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.18', 'Que sinal você nos mostra', 'Τί σημεῖον δεικνύεις ἡμῖν - *Ti sēmeion deiknyeis hēmin*', 'Em vez de examinarem se a repreensão moral de Jesus correspondia à Torá e aos profetas, as autoridades exigem uma credencial sobrenatural que autentique a Sua autoridade jurisdicional sobre o Templo (cf. Mt 12:38; 1Co 1:22: "os judeus pedem sinais").', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.19', 'JHN.2', 'JHN', 2, 19, 'ἀπεκρίθη Ἰησοῦς καὶ εἶπεν αὐτοῖς· Λύσατε τὸν ναὸν τοῦτον καὶ ἐν τρισὶν ἡμέραις ἐγερῶ αὐτόν.', 'Respondeu Jesus e disse a eles: Destruí o santuário este e em três dias levantarei ele.', 'Jesus lhes respondeu: “Destruam este santuário, e em três dias eu o levantarei”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.2.19', 'JESUS', 23, 78, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.19', 'Destruam', 'Λύσατε - *Lysate*', 'Imperativo aoristo ativo de *lyō* ("desatar", "dissolver", "destruir"). Trata-se de um imperativo com força permissiva ou condicional no hebraísmo profético ("Se vocês destruírem..."), prenunciando a consumação da culpa da liderança judaica que levaria o Messias à morte.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.19', 'este santuário', 'τὸν ναὸν τοῦτον - *ton naon touton*', 'Diferente de *hieron* (o complexo arquitetônico exterior do Templo citado nos vv. 14-15), *naos* refere-se exclusivamente ao santuário interno, a morada íntima onde Deus habita (*Shekinah*). Jesus projeta uma metáfora cósmica: Seu próprio corpo humano encarnado é o verdadeiro *naos* onde a plenitude da divindade reside corporalmente (Cl 2:9).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.19', 'em três dias eu o levantarei', 'ἐν τρισὶν ἡμέραις ἐγερῶ αὐτόν - *en trisin hēmerais egerō auton*', 'Profecia inequívoca de Sua própria ressurreição física dentre os mortos ao terceiro dia. O verbo *egeirō* ("levantar", "erguer", "ressuscitar") afirma o poder e a autoridade ativa de Cristo sobre a Sua própria vida e ressurreição (cf. Jo 10:18).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.20', 'JHN.2', 'JHN', 2, 20, 'εἶπαν οὖν οἱ Ἰουδαῖοι· Τεσσεράκοντα καὶ ἓξ ἔτεσιν οἰκοδομήθη ὁ ναὸς οὗτος, καὶ σὺ ἐν τρισὶν ἡμέραις ἐγερεῖς αὐτόν;', 'Disseram então os judeus: Quarenta e seis anos foi edificado o santuário este, e tu em três dias levantarás ele?', 'As autoridades judaicas disseram então: “Em quarenta e seis anos foi edificado este santuário, e você vai levantá-lo em três dias?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.20', 'quarenta e seis anos', 'Τεσσεράκοντα καὶ ἓξ ἔτεσιν - *Tesserakonta kai hex etesin*', 'Dativo de tempo ou duração. Segundo o historiador Flávio Josefo (*Antiguidades Judaicas* 15.380), Herodes, o Grande, iniciou o grandioso projeto de reconstrução e ampliação do Segundo Templo no 18º ano de seu reinado (aproximadamente 20/19 a.C.). Somando 46 anos a essa data, chega-se com precisão histórica à Páscoa do ano 27 ou 28 d.C., confirmando a cronologia interna do Evangelho. O complexo como um todo continuou em obras até por volta de 63 d.C., apenas sete anos antes de ser totalmente arrasado pelas legiões romanas de Tito em 70 d.C.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.20', 'você vai levantá-lo', 'σὺ ... ἐγερεῖς αὐτόν - *sy ... egereis auton*', 'O pronome *sy* ("você") é pré-posto de modo altamente cético e irônico, enfatizando a suposta presunção daquele rabi galileu sem credenciais sacerdotais diante da monumental obra arquitetônica herodiana.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.21', 'JHN.2', 'JHN', 2, 21, 'ἐκεῖνος δὲ ἔλεγεν περὶ τοῦ ναοῦ τοῦ σώματος αὐτοῦ.', 'Aquele porém falava acerca do santuário do corpo dele.', 'Ele, porém, falava do santuário do seu corpo.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.21', 'o santuário do seu corpo', 'τοῦ ναοῦ τοῦ σώματος αὐτοῦ - *tou naou tou sōmatos autou*', 'Genitivo epexegético ou de aposição ("o santuário, que é o seu corpo"). O narrador joanino desfaz a incompreensão das autoridades: o Templo de pedra de Jerusalém, tornado obsoleto pelo comércio e pela corrupção, é definitivamente superado pelo corpo ressurreto de Cristo, o novo centro de adoração espiritual e reconciliação entre Deus e a humanidade (cf. Jo 4:21-24).', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.22', 'JHN.2', 'JHN', 2, 22, 'ὅτε οὖν ἠγέρθη ἐκ νεκρῶν, ἐμνήσθησαν οἱ μαθηταὶ αὐτοῦ ὅτι τοῦτο ἔλεγεν, καὶ ἐπίστευσαν τῇ γραφῇ καὶ τῷ λόγῳ ὃν εἶπεν ὁ Ἰησοῦς.', 'Quando então foi levantado dentre mortos, lembraram-se os discípulos dele que isto dizia, e creram na Escritura e na palavra que disse o Jesus.', 'Portanto, quando ele ressuscitou dentre os mortos, seus discípulos lembraram-se de que ele dizia isso; e creram na Escritura e na palavra que Jesus tinha dito.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.22', 'quando ele ressuscitou dentre os mortos', 'ὅτε οὖν ἠγέρθη ἐκ νεκρῶν - *hote oun ēgerthē ek nekrōn*', 'Aoristo passivo (*passivum divinum*) de *egeirō*, assinalando a ressurreição operada pelo poder soberano de Deus como a chave hermenêutica retrospectiva indispensável para a plena compreensão dos ensinos enigmáticos de Jesus durante Seu ministério terreno.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.22', 'creram na Escritura e na palavra', 'ἐπίστευσαν τῇ γραφῇ καὶ τῷ λόγῳ - *episteusan tē graphē kai tō logō*', '*Graphē* (a Escritura do Antigo Testamento que predizia a ressurreição messiânica, como o Sl 16:10 e Is 53:10-12) e o *logos* (a declaração oral de Jesus no v. 19) são colocados sob o mesmo nível de autoridade e inspiração divina.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.23', 'JHN.2', 'JHN', 2, 23, 'Ὡς δὲ ἦν ἐν τοῖς Ἱεροσολύμοις ἐν τῷ πάσχα ἐν τῇ ἑορτῇ, πολλοὶ ἐπίστευσαν εἰς τὸ ὄνομα αὐτοῦ, θεωροῦντες αὐτοῦ τὰ σημεῖα ἃ ἐποίει·', 'Quando porém estava em Jerusalém na páscoa na festa, muitos creram no nome dele, contemplando dele os sinais que fazia;', 'Enquanto ele estava em Jerusalém durante a festa da Páscoa, muitos creram no seu nome, ao verem os sinais que ele realizava.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.23', 'muitos creram no seu nome', 'πολλοὶ ἐπίστευσαν εἰς τὸ ὄνομα αὐτοῦ - *polloi episteusan eis to onoma autou*', 'A fórmula *pisteuō eis to onoma* indica adesão inicial. Contudo, o contexto revela que essa fé era superficial e baseada primariamente no deslumbramento com os prodígios miraculosos.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.23', 'ao verem os sinais', 'θεωροῦντες αὐτοῦ τὰ σημεῖα - *theōrountes autou ta sēmeia*', 'O particípio presente *theōrountes* (do verbo *theōreō*, "olhar atentamente", "ser espectador") sublinha a postura de observadores fascinados pelo espetáculo visual dos milagres (*sēmeia*). O Quarto Evangelho estabelece distinção qualitativa entre uma fé frágil estimulada por milagres visíveis e a fé autêntica e madura que se apega à Palavra e à pessoa de Cristo (cf. Jo 4:48; 20:29).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.24', 'JHN.2', 'JHN', 2, 24, 'αὐτὸς δὲ Ἰησοῦς οὐκ ἐπίστευεν αὑτὸν αὐτοῖς διὰ τὸ αὐτὸν γινώσκειν πάντας', 'O próprio porém Jesus não confiava a si mesmo a eles por causa do ele conhecer todos,', 'Mas o próprio Jesus não confiava a si mesmo a eles, porque conhecia a todos,');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.24', 'não confiava a si mesmo a eles', 'οὐκ ἐπίστευεν αὑτὸν αὐτοῖς - *ouk episteuen hauton autois*', 'Paranomásia e jogo teológico magistral com o verbo *pisteuō* entre os versículos 23 e 24: enquanto muitos "creram" (*episteusan*, aoristo) n’Ele pelos sinais, Jesus não "confiava/entregava" (*ouk episteuen*, imperfeito contínuo) Sua pessoa a eles. O verbo grego abrange tanto a atitude de crer quanto o ato de confiar/depositar custódia. Jesus discerne que a fé meramente entusiasta e utilitária da multidão não constituía discipulado verdadeiro e comprometido.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.24', 'porque conhecia a todos', 'διὰ τὸ αὐτὸν γινώσκειν πάντας - *dia to auton ginōskein pantas*', 'Construção causal com a preposição *dia* e o infinitivo articular (*to ginōskein*). Revela a onisciência divina de Jesus: Ele penetra a consciência e a motivação íntima de cada ser humano, imune a bajulações ou falsos entusiasmos populares.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.2.25', 'JHN.2', 'JHN', 2, 25, 'καὶ ὅτι οὐ χρείαν εἶχεν ἵνα τις μαρτυρήσῃ περὶ τοῦ ἀνθρώπου, αὐτὸς γὰρ ἐγίνωσκεν τί ἦν ἐν τῷ ἀνθρώπῳ.', 'e porque não necessidade tinha para que alguém testemunhasse acerca do homem, ele pois conhecia o que era no homem.', 'e não precisava de que ninguém testemunhasse a respeito do ser humano, pois ele próprio conhecia o que havia no ser humano.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.25', 'não precisava de que ninguém testemunhasse', 'οὐ χρείαν εἶχεν ἵνα τις μαρτυρήσῃ - *ou chreian eichen hina tis martyrēsē*', 'O vocabulário jurídico de testemunho (*martyria* / *martyreō*) reaparece aqui. Jesus não depende de relatórios, diagnósticos ou testemunhos humanos para avaliar o caráter das pessoas.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.2.25', 'ele próprio conhecia o que havia no ser humano', 'αὐτὸς γὰρ ἐγίνωσκεν τί ἦν ἐν τῷ ἀνθρώπῳ - *autos gar eginōsken ti ēn en tō anthrōpō*', 'Nas Escrituras Hebraicas, perscrutar as profundezas do coração e da mente humana é uma prerrogativa exclusiva e inalienável do Deus Altíssimo (1Sm 16:7; 1Rs 8:39; Sl 139:1-4; Jr 17:9-10). Ao atribuir a Jesus esse conhecimento soberano e infalível do interior do homem (*anthrōpos*), João encerra o capítulo 2 reafirmando a divindade transcendente da Palavra Encarnada e preparando a transição imediata para o diálogo com Nicodemos em João 3:1 ("Ora, havia um homem dos fariseus...").', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.1', 'JHN.3', 'JHN', 3, 1, 'Ἦν δὲ ἄνθρωπος ἐκ τῶν Φαρισαίων, Νικόδημος ὄνομα αὐτῷ, ἄρχων τῶν Ἰουδαίων·', 'Havia porém um homem dentre os fariseus, Nicodemos nome a ele, autoridade das autoridades judaicas;', 'Havia entre os fariseus um homem; seu nome era Nicodemos, autoridade judaica.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.1', 'fariseus', 'ἐκ τῶν Φαρισαίων - *ek tōn Pharisaiōn*', 'Movimento religioso e leigo de grande prestígio popular e rigor doutrinário no judaísmo do Segundo Templo. Os fariseus caracterizavam-se pela observância minuciosa da Torá escrita e da tradição oral interpretativa (*Halakhá*), zelando pela pureza ritual, dízimos e separação de influências pagãs. Nicodemos representa a elite instruída e devota de Jerusalém que se aproxima de Jesus para avaliar suas credenciais teológicas.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.1', 'seu nome era Nicodemos', 'Νικόδημος - *Nikodēmos*', 'Nome grego que significa "vencedor com o povo" (*nikē* + *dēmos*), comum entre famílias judaicas aristocráticas e helenizadas da Judeia. Nicodemos reaparece em momentos decisivos no Quarto Evangelho: em João 7:50, defendendo no Sinédrio o direito legal de Jesus a um julgamento justo conforme a Lei; e em 19:39, unindo-se a José de Arimateia para ungir e sepultar dignamente o corpo crucificado do Messias com cerca de cem libras de mirra e aloés.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.1', 'autoridade judaica', 'ἄρχων τῶν Ἰουδαίων - *archōn tōn Ioudaiōn*', 'O termo *archōn* ("governante", "líder", "magistrado") indica que Nicodemos era membro oficial do Sinédrio (*Sanhedrin*), o tribunal supremo e conselho administrativo judaico em Jerusalém, composto por 71 membros (sumos sacerdotes, anciãos aristocratas e escribas fariseus). Conforme a diretriz do glossário para *hoi Ioudaioi* em função de liderança governante/interlocutora de Jerusalém, verte-se por "autoridade judaica".', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.2', 'JHN.3', 'JHN', 3, 2, 'οὗτος ἦλθεν πρὸς αὐτὸν νυκτὸς καὶ εἶπεν αὐτῷ· Ῥαββί, οἴδαμεν ὅτι ἀπὸ θεοῦ ἐλήλυθας διδάσκαλος· οὐδεὶς γὰρ δύναται ταῦτα τὰ σημεῖα ποιεῖν ἃ σὺ ποιεῖς, ἐὰν μὴ ᾖ ὁ θεὸς μετ’ αὐτοῦ.', 'Este veio para ele de noite e disse a ele: Rabi, sabemos que de Deus vieste mestre; ninguém pois pode estes os sinais fazer que tu fazes, se não for o Deus com ele.', 'Ele veio a Jesus de noite e lhe disse: “Rabi, sabemos que você veio de Deus como mestre; pois ninguém pode fazer estes sinais que você faz se Deus não estiver com ele”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.2', 'de noite', 'νυκτός - *nyktos*', 'Genitivo de tempo. Sob o ponto de vista prático e histórico, a noite proporcionava o silêncio necessário para debates teológicos aprofundados entre mestres e discrição diante da vigilância crítica de seus pares do Sinédrio. No simbolismo teológico do Quarto Evangelho, porém, a noite (*nyx*) representa o reino das trevas, da cegueira espiritual e da ignorância que ainda envolve Nicodemos (cf. Jo 9:4; 11:10; 13:30). Ele inicia sua trajetória saindo da noite em direção à verdadeira Luz (*to phōs*).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.2', 'Rabi', 'Ῥαββί - *Rhabbi*', 'Tratamento honorífico aramaico ("meu mestre" ou "meu grande"), formalmente respeitoso. Nicodemos aproxima-se de Jesus em pé de igualdade profissional, como um colega acadêmico que reconhece a habilidade pedagógica de Jesus, sem ainda discernir Sua identidade messiânica e divina transcendente.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.2', 'você veio de Deus como mestre', 'ἀπὸ θεοῦ ἐλήλυθας διδάσκαλος - *oidamen*', 'Plural representativo ou corporativo ("nós sabemos"). Nicodemos apresenta-se como porta-voz de um grupo de observadores e membros da elite religiosa impressionados com os prodígios ocorridos durante a Páscoa (Jo 2:23).', 3);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.2', 'sinais', 'τὰ σημεῖα - *ta sēmeia*', 'Nicodemos fundamenta sua conclusão nos *sēmeia* visíveis. No entanto, o Evangelho de João já advertiu em 2:23-25 que a fé estimulada primariamente por milagres é incipiente e inadequada para a verdadeira comunhão com o Reino de Deus.', 4);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.3', 'JHN.3', 'JHN', 3, 3, 'ἀπεκρίθη Ἰησοῦς καὶ εἶπεν αὐτῷ· Ἀμὴν ἀμὴν λέγω σοι, ἐὰν μή τις γεννηθῇ ἄνωθεν, οὐ δύναται ἰδεῖν τὴν βασιλείαν τοῦ θεοῦ.', 'Respondeu Jesus e disse a ele: Em verdade em verdade digo a ti, se não alguém for gerado do alto, não pode ver o reino de Deus.', 'Jesus respondeu e lhe disse: “Em verdade, em verdade lhe digo: se alguém não nascer do alto, não pode ver o Reino de Deus”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.3', 'JESUS', 30, 121, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.3', 'Em verdade, em verdade', 'Ἀμὴν ἀμὴν - *Amēn amēn*', 'Solene fórmula de asseveração de autoridade divina e certeza absoluta, repetida 25 vezes com exclusividade nos lábios de Jesus no Evangelho de João. Deriva da raiz hebraica de fidelidade e estabilidade (*''āman*).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.3', 'nascer do alto', 'γεννηθῇ ἄνωθεν - *gennēthē anōthen*', 'O advérbio grego *anōthen* encerra uma polissemia deliberada: possui tanto sentido espacial e vertical ("de cima", "do alto", "de Deus") quanto sentido temporal ("de novo", "uma segunda vez"). Em todas as outras ocorrências no corpus joanino (Jo 3:31; 19:11; 19:23), *anōthen* significa invariavelmente "do alto". Essa ambiguidade é o motor propulsor de todo o diálogo: Jesus proclama a necessidade imperiosa de uma regeneração ontológica e espiritual originada nos céus, enquanto Nicodemos no v. 4 entende equivocadamente no sentido de uma repetição biológica horizontal (*deuteron*, "uma segunda vez"). O português é obrigado a optar por um termo; a tradução por "do alto" preserva com rigor a intenção teológica de Jesus, enquanto a resposta de Nicodemos no versículo seguinte expõe o mal-entendido.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.3', 'ver o Reino de Deus', 'ἰδεῖν τὴν βασιλείαν τοῦ θεοῦ - *idein tēn basileian tou theou*', 'No hebraísmo bíblico e joanino, o verbo "ver" (*idein*) equivale a experimentar pessoalmente, herdar ou participar de uma realidade (cf. Jo 3:36; Sl 34:12). O termo "Reino de Deus" (*hē basileia tou theou*), onipresente nos Sinóticos, ocorre apenas duas vezes em João (3:3, 5), designando a esfera da soberania salvífica e da vida eterna inaugurada por Deus.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.4', 'JHN.3', 'JHN', 3, 4, 'λέγει πρὸς αὐτὸν ὁ Νικόδημος· Πῶς δύναται ἄνθρωπος γεννηθῆναι γέρων ὤν; μὴ δύναται εἰς τὴν κοιλίαν τῆς μητρὸς αὐτοῦ δεύτερον εἰσελθεῖν καὶ γεννηθῆναι;', 'Diz para ele o Nicodemos: Como pode um homem nascer velho sendo? Acaso pode no ventre da mãe dele uma segunda vez entrar e nascer?', 'Nicodemos lhe disse: “Como pode um homem nascer sendo velho? Pode acaso entrar uma segunda vez no ventre de sua mãe e nascer?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.4', 'sendo velho', 'γέρων ὤν - *gerōn ōn*', 'Particípio presente de *eimi* com o substantivo *gerōn* ("ancião"). Ilustra o raciocínio estritamente empírico e materialista de Nicodemos, que tenta enquadrar a transcendência da nova criação divina nos limites das leis da obstetrícia e da biologia humana.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.4', 'Pode acaso entrar uma segunda vez', 'δεύτερον - *deuteron*', 'O advérbio *deuteron* esclarece com precisão cirúrgica a má interpretação de Nicodemos: ele captou *anōthen* apenas sob o viés temporal de reiteração carnal ("pela segunda vez"), ignorando a dimensão vertical da regeneração celestial ("do alto"). A partícula grega *mē*, que encabeça a segunda interrogação, formula uma pergunta que gramaticalmente antecipa uma resposta negativa peremptória ("é impossível, não é?").', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.5', 'JHN.3', 'JHN', 3, 5, 'ἀπεκρίθη Ἰησοῦς· Ἀμὴν ἀμὴν λέγω σοι, ἐὰν μή τις γεννηθῇ ἐξ ὕδατος καὶ πνεύματος, οὐ δύναται εἰσελθεῖν εἰς τὴν βασιλείαν τοῦ θεοῦ.', 'Respondeu Jesus: Em verdade em verdade digo a ti, se não alguém for gerado de água e espírito, não pode entrar no reino de Deus.', 'Jesus respondeu: “Em verdade, em verdade lhe digo: se alguém não nascer da água e do Espírito, não pode entrar no Reino de Deus.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.5', 'JESUS', 18, 127, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.5', 'da água e do Espírito', 'ἐξ ὕδατος καὶ πνεύματος - *ex hydatos kai pneumatos*', 'Ambas as palavras são coordenadas sob uma única preposição de origem (*ek*), constituindo um conceito teológico indivisível. A exegese bíblica discute as seguintes leituras principais: (1) *Alusão à profecia escatológica de Ezequiel 36:25-27:* a leitura mais provável no diálogo com um "mestre de Israel" (v. 10), na qual Yahweh promete purificar Seu povo aspergindo "água pura" de suas impurezas idolátricas e infundir em seus corações um "Espírito novo" na era messiânica; (2) *O batismo de arrependimento de João e o batismo do Espírito conferido por Jesus:* a água representaria o rito preparatório e o Espírito a nova criação messiânica (cf. Jo 1:31-33); (3) *Hendíadis teológica:* "da água, que é o Espírito", onde a água atua como símbolo clássico da ação vivificante e purificadora do Espírito Santo (cf. Jo 7:38-39); (4) *Nascimento físico e espiritual:* a água representaria o fluido amniótico da geração biológica humana e o Espírito o nascimento espiritual (leitura menos provável face à sintaxe grega de artigo unificado).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.5', 'entrar no Reino de Deus', 'εἰσελθεῖν εἰς τὴν βασιλείαν τοῦ θεοῦ - *eiselthein eis tēn basileian tou theou*', 'Paralelo exegético ao "ver o Reino" do v. 3. O acesso à comunidade e ao domínio redentor de Deus não se conquista por nascimento genealógico judaico, obediência legalista ou mérito humano, mas requer uma transformação ontológica absoluta operada soberanamente por Deus.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.6', 'JHN.3', 'JHN', 3, 6, 'τὸ γεγεννημένον ἐκ τῆς σαρκὸς σάρξ ἐστιν, καὶ τὸ γεγεννημένον ἐκ τοῦ πνεύματος πνεῦμά ἐστιν.', 'O que foi gerado da carne carne é, e o que foi gerado do espírito espírito é.', 'O que é nascido da carne é carne, e o que é nascido do Espírito é espírito.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.6', 'JESUS', 0, 74, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.6', 'O que é nascido da carne é carne', 'τὸ γεγεννημένον ἐκ τῆς σαρκὸς σάρξ ἐστιν - *to gegennēmenon ek tēs sarkos sarx estin*', 'O particípio perfeito neutro *to gegennēmenon* indica a condição permanente resultante do ato de geração. O termo *sarx* ("carne") denota no pensamento bíblico a humanidade em sua fragilidade congênita, finitude terrena e impotência moral para alcançar a vida divina por esforço próprio. A esfera natural só é capaz de reproduzir sua própria limitação.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.6', 'o que é nascido do Espírito é espírito', 'τὸ γεγεννημένον ἐκ τοῦ πνεύματος πνεῦμά ἐστιν - *to gegennēmenon ek tou pneumatos pneuma estin*', 'Estabelece o abismo ontológico intransponível entre a ordem criada e a ordem da graça. A vida sobrenatural do Reino decorre exclusivamente da ação do Espírito Santo (*to pneuma*), gerando no crente uma nova faculdade de comunhão com Deus.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.7', 'JHN.3', 'JHN', 3, 7, 'μὴ θαυμάσῃς ὅτι εἶπόν σοι Δεῖ ὑμᾶς γεννηθῆναι ἄνωθεν.', 'Não te admires de que disse a ti: É necessário vós serdes gerados do alto.', 'Não se admire de eu lhe ter dito: ‘Vocês precisam nascer do alto’.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.7', 'JESUS', 0, 65, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.7', 'Não se admire', 'μὴ θαυμάσῃς - *mē thaumasēs*', 'Subjuntivo aoristo proibitivo com a partícula negativa *mē*, advertindo para a superação do espanto intelectual estéril diante do mistério da revelação.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.7', 'Vocês precisam', 'Δεῖ ὑμᾶς - *Dei hymas*', 'Transição crucial na pessoa gramatical: Jesus usa o pronome singular *soi* ("a você") na introdução e muda para o pronome plural *hymas* ("vós / vocês") no imperativo da citação. O verbo impessoal *dei* assinala a necessidade divina categórica e indeclinável do plano salvífico. A exigência da regeneração celestial não se restringe a Nicodemos, mas abrange o Sinédrio, a nação de Israel e todos os seres humanos.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.7', 'nascer do alto', 'γεννηθῆναι ἄνωθεν - *gennēthēnai anōthen*', 'Infinitivo aoristo passivo reafirmando o princípio de consistência editorial R6: a salvação é um dom que descende verticalmente "do alto", e não uma conquista moral de baixo para cima.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.8', 'JHN.3', 'JHN', 3, 8, 'τὸ πνεῦμα ὅπου θέλει πνεῖ, καὶ τὴν φωνὴν αὐτοῦ ἀκούεις, ἀλλ’ οὐκ οἶδας πόθεν ἔρχεται καὶ ποῦ ὑπάγει· οὕτως ἐστὶν πᾶς ὁ γεγεννημένος ἐκ τοῦ πνεύματος.', 'O vento/espírito onde quer sopra, e o som/voz dele ouves, mas não sabes de onde vem e para onde vai; assim é todo o que foi gerado do espírito/Espírito.', 'O vento sopra onde quer, e você ouve o seu som, mas não sabe de onde ele vem nem para onde vai; assim é todo aquele que é nascido do Espírito”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.8', 'JESUS', 0, 141, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.8', 'O vento sopra ... do Espírito', 'τὸ πνεῦμα ... πνεῖ ... ἐκ τοῦ πνεύματος - *to pneuma ... pnei ... ek tou pneumatos*', 'Paranomásia e trocadilho intrínseco e monumental entre o grego *pneuma* e o hebraico *ruach*, termos polissêmicos que significam tanto o "vento" físico e atmosférico quanto o "Espírito" divino. O verbo cognato *pnei* ("sopra", "resfria") estabelece uma analogia fenomenológica indispensável: o vento move-se com soberania autônoma (*hopou thelei*), seus efeitos audíveis e visíveis são inegavelmente percebidos (*tēn phōnēn autou akoueis*), mas seus limites de origem e destino permanecem invisíveis e incontroláveis pelo ser humano (*ouk oidas pothen erchetai kai pou hypagei*). Do mesmo modo atua o Espírito Santo: Sua soberana operação regeneradora é invisível aos olhos carnais, porém real, dinâmica e demonstrada pelas transformações morais palpáveis na vida dos que nascem de Deus.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.9', 'JHN.3', 'JHN', 3, 9, 'ἀπεκρίθη Νικόδημος καὶ εἶπεν αὐτῷ· Πῶς δύναται ταῦτα γενέσθαι;', 'Respondeu Nicodemos e disse a ele: Como podem estas coisas acontecer?', 'Nicodemos respondeu e lhe disse: “Como pode ser isso?”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.9', 'Como pode ser isso', 'Πῶς δύναται ταῦτα γενέσθαι - *Pōs dynatai tauta genesthai*', 'Literalmente, "Como podem estas coisas vir a existir/acontecer?". Nicodemos reitera a interrogação de perplexidade (*Pōs dynatai*, cf. v. 4), evidenciando a paralisia hermenêutica e epistemológica de um sistema religioso letrado que, apegado a regulamentações humanas e categorias terrenas, torna-se incapaz de assimilar o agir soberano e vivificante da graça divina.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.10', 'JHN.3', 'JHN', 3, 10, 'ἀπεκρίθη Ἰησοῦς καὶ εἶπεν αὐτῷ· Σὺ εἶ ὁ διδάσκαλος τοῦ Ἰσραὴλ καὶ ταῦτα οὐ γινώσκεις;', 'Respondeu Jesus e disse a ele: Tu és o mestre do Israel e estas coisas não conheces?', 'Jesus respondeu e lhe disse: “Você é o mestre de Israel e não compreende estas coisas?');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.10', 'JESUS', 30, 86, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.10', 'o mestre de Israel', 'ὁ διδάσκαλος τοῦ Ἰσραήλ - *ho didaskalos tou Israēl*', 'O emprego enfático do artigo definido *ho* ("o mestre") ressalta a proeminência notória e a alta reputação de Nicodemos como eminente expoente do saber teológico e doutor respeitado em toda a nação.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.10', 'não compreende estas coisas', 'ταῦτα οὐ γινώσκεις - *tauta ou ginōskeis*', 'A repreensão de Jesus evidencia o contraste trágico entre o domínio técnico dos detalhes da tradição rabínica e o desconhecimento do coração das Escrituras Hebraicas. O Antigo Testamento já havia proclamado reiteradamente a necessidade da circuncisão interior do coração e da infusão do Espírito escatológico para a renovação do povo de Deus (Dt 30:6; Jr 31:31-34; Ez 36:25-27; Jl 2:28-29).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.11', 'JHN.3', 'JHN', 3, 11, 'ἀμὴν ἀμὴν λέγω σοι ὅτι ὃ οἴδαμεν λαλοῦμεν καὶ ὃ ἑωράκαμεν μαρτυροῦμεν, καὶ τὴν μαρτυρίαν ἡμῶν οὐ λαμβάνετε.', 'Em verdade em verdade digo a ti que o que sabemos falamos e o que temos visto testemunhamos, e o testemunho de nós não recebeis.', 'Em verdade, em verdade lhe digo que nós falamos do que sabemos e testemunhamos do que vimos, mas vocês não recebem o nosso testemunho.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.11', 'JESUS', 0, 133, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.11', 'nós falamos ... testemunhamos', 'ὃ οἴδαμεν λαλοῦμεν καὶ ὃ ἑωράκαμεν μαρτυροῦμεν - *ho oidamen laloumen kai ho heōrakamen martyroumen*', 'O uso do plural por Jesus contrasta criticamente com o "sabemos" (*oidamen*) presunçoso de Nicodemos no v. 2. A revelação de Jesus não nasce de deduções humanas incertas, mas da comunhão e contemplação ocular direta entre o Pai e o Filho (ou da comunidade profética do Messias).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.11', 'o nosso testemunho', 'τὴν μαρτυρίαν ἡμῶν - *tēn martyrian hēmōn*', 'Vocabulário forense basilar em João (cf. Jo 1:7, 19). A proclamação do evangelho opera como um testemunho judicial fidedigno apresentado diante do mundo.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.11', 'vocês não recebem', 'οὐ λαμβάνετε - *ou lambanete*', 'Mudança para o plural, confrontando a incredulidade institucional e generalizada das autoridades de Jerusalém (cf. Jo 1:11).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.12', 'JHN.3', 'JHN', 3, 12, 'εἰ τὰ ἐπίγεια εἶπον ὑμῖν καὶ οὐ πιστεύετε, πῶς ἐὰν εἴπω ὑμῖν τὰ ἐπουράνια πιστεύσετε;', 'Se as coisas terrenas disse a vós e não credes, como se disser a vós as celestes crereis?', 'Se eu lhes falei de coisas terrenas e vocês não creem, como crerão se eu lhes falar das celestiais?');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.12', 'JESUS', 0, 99, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.12', 'coisas terrenas', 'τὰ ἐπίγεια - *ta epigeia*', 'As ilustrações e processos espirituais observáveis e experimentados no âmbito terreno da existência humana (o nascimento, o vento, a água, a purificação).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.12', 'celestiais', 'τὰ ἐπουράνια - *ta epourania*', 'Os conselhos e decretos eternos de Deus no céu sobre a redenção universal, a pré-existência divina do Filho, a glorificação mediante a cruz e a vida intratrinitária.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.12', 'não creem ... crerão', 'οὐ πιστεύετε ... πιστεύσετε - *ou pisteuete ... pisteusete*', 'O verbo de fé e adesão pactual *pisteuō* surge no presente e futuro, enfatizando a confiança pessoal na Palavra de Cristo como a única ponte epistêmica para a compreensão das realidades celestiais.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.13', 'JHN.3', 'JHN', 3, 13, 'καὶ οὐδεὶς ἀναβέβηκεν εἰς τὸν οὐρανὸν εἰ μὴ ὁ ἐκ τοῦ οὐρανοῦ καταβάς, ὁ υἱὸς τοῦ ἀνθρώπου.', 'E ninguém subiu ao céu a não ser aquele que do céu desceu, o Filho do Homem.', 'Ninguém subiu ao céu, a não ser aquele que desceu do céu: o Filho do Homem.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.13', 'JESUS', 0, 74, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.13', 'Ninguém subiu ao céu', 'οὐδεὶς ἀναβέβηκεν εἰς τὸν οὐρανόν - *oudeis anabebēken eis ton ouranon*', 'Declaração que contrapõe certas tradições apocalípticas e místicas do judaísmo helenístico e do Segundo Templo (atestadas em obras apócrifas como 1 Enoque e Testamento dos Doze Patriarcas), as quais afirmavam que heróis do passado, como Moisés ou Enoque, teriam ascendido corporalmente aos céus para receber segredos esotéricos de Deus. Jesus assevera que nenhum ser humano jamais subiu por sua própria capacidade à morada celestial para perscrutar a mente divina (cf. Dt 30:12; Pv 30:4).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.13', 'o Filho do Homem', 'ὁ υἱὸς τοῦ ἀνθρώπου - *ho hyios tou anthrōpou*', 'Título messiânico e escatológico predileto de Jesus, oriundo de Daniel 7:13-14. Na teologia do Quarto Evangelho, o Filho do Homem é o ser celestial preexistente que desceu (*katabas*) na Encarnação para ser o revelador definitivo do Pai e que ascenderá (*anabebēken*) ao céu mediante Sua exaltação e glorificação na cruz.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.14', 'JHN.3', 'JHN', 3, 14, 'καὶ καθὼς Μωϋσῆς ὕψωσεν τὸν ὄφιν ἐν τῇ ἐρήμῳ, οὕτως ὑψωθῆναι δεῖ τὸν υἱὸν τοῦ ἀνθρώπου,', 'E assim como Moisés levantou a serpente no deserto, assim ser levantado é necessário o Filho do Homem,', 'E, assim como Moisés levantou a serpente no deserto, assim é necessário que o Filho do Homem seja levantado,');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.14', 'JESUS', 0, 107, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.14', 'Moisés levantou a serpente no deserto', 'Μωϋσῆς ὕψωσεν τὸν ὄφιν ἐν τῇ ἐρήμῳ - *Mōysēs hypsōsen ton ophin en tē erēmō*', 'Correspondência tipológica direta com a narrativa de Números 21:4-9. Quando os israelitas rebeldes foram mordidos por serpentes ardentes no deserto, Deus ordenou a Moisés que fundisse uma serpente de bronze e a elevasse sobre uma haste; qualquer pessoa picada que olhasse com fé para a serpente erguida recebia cura e preservação física. Pelo prisma cristológico joanino, o próprio emblema da maldição e do pecado é transformado por Deus em instrumento soberano de redenção para os que creem.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.14', 'seja levantado', 'ὑψωθῆναι - *hypsōthēnai*', 'Infinitivo aoristo passivo de *hypsoō*, portador de um magistral duplo sentido próprio da teologia joanina: denota simultaneamente o ato físico de ser erguido e pregado na madeira da cruz perante o mundo (cf. Jo 8:28; 12:32-33) e a suprema exaltação e entronização triunfal do Filho em glória perante o cosmos (cf. Is 52:13 LXX). No Quarto Evangelho, a crucificação não é concebida como mera tragédia ou humilhação, mas como a manifestação máxima da majestade régia do Messias.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.14', 'é necessário', 'δεῖ - *dei*', 'Aponta para a necessidade teleológica irrevogável do plano salvífico estabelecido soberanamente pelo Pai na eternidade.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.15', 'JHN.3', 'JHN', 3, 15, 'ἵνα πᾶς ὁ πιστεύων ἐν αὐτῷ ἔχῃ ζωὴν αἰώνιον.', 'para que todo o que crê nele tenha vida eterna.', 'para que todo aquele que nele crê tenha a vida eterna”.');
INSERT INTO verse_speech_spans (verse_id, speaker, start_offset, end_offset, order_index) VALUES ('JHN.3.15', 'JESUS', 0, 53, 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.15', 'todo aquele que nele crê', 'πᾶς ὁ πιστεύων ἐν αὐτῷ - *pas ho pisteuōn en autō*', 'A salvação torna-se universalmente disponível a qualquer ser humano sem distinção de etnia ou linhagem abraâmica, exigindo a atitude de fé contínua e perseverante (*ho pisteuōn*, particípio presente). Crer em Jesus equivale a contemplar e acolher com fé o Messias levantado na cruz, espelhando os israelitas que fitavam a serpente no deserto.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.15', 'vida eterna', 'ζωὴν αἰώνιον - *zōēn aiōnion*', 'Primeira ocorrência desta expressão basilar no Evangelho de João (onde ocorre 17 vezes). No grego koiné joanino, a vida eterna (*zōē aiōnios*) não se define apenas pela extensão temporal sem fim, mas pela comunhão presente com a vida divina incorruptível, comunicada desde já ao crente na história (cf. Jo 17:3).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.15', 'Fronteira do discurso de Jesus', 'R11', 'Em conformidade com a regra editorial do projeto, o discurso direto de Jesus a Nicodemos encerra-se formalmente no versículo 15. A partir do versículo 16, a narrativa transita para a reflexão teológica do evangelista.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.16', 'JHN.3', 'JHN', 3, 16, 'Οὕτως γὰρ ἠγάπησεν ὁ θεὸς τὸν κόσμον ὥστε τὸν υἱὸν τὸν μονογενῆ ἔδωκεν, ἵνα πᾶς ὁ πιστεύων εἰς αὐτὸν μὴ ἀπόληται ἀλλὰ ἔχῃ ζωὴν αἰώνιον.', 'Assim pois amou o Deus o mundo, de modo que o Filho o único deu, para que todo o que crê nele não pereça mas tenha vida eterna.', 'Pois assim Deus amou o mundo: deu o seu Filho único, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.16', 'assim Deus amou', 'Οὕτως ... ἠγάπησεν ὁ θεός - *Houtōs ... ēgapēsen ho theos*', 'O advérbio grego *houtōs* expressa estritamente modo ou maneira ("assim", "deste modo", "desta forma"), e não grau quantitativo ou intensidade emocional ("tanto", "de tal maneira"). Ele conecta-se retrospectivamente ao modo como a serpente foi levantada (vv. 14-15) e aponta diretamente para o ato histórico culminante da doação sacrificial do Filho. A leitura tradicional de certas traduções vernáculas ("amou de tal maneira que" ou "amou tanto o mundo que") comete o equívoco exegético de converter modo em intensidade psicológica, obscurecendo a ênfase cristológica na manifestação histórica objetiva do amor do Pai na cruz. A oração de resultado introduzida por *hōste* com o indicativo (*edōken*, "deu") não milita contra essa leitura: *hōste* seguido de indicativo enuncia resultado efetivamente ocorrido, não intensidade — "assim amou o mundo, de modo que deu". A grandeza, portanto, não está no advérbio nem na conjunção, mas na identidade do dom.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.16', 'Filho único', 'τὸν υἱὸν τὸν μονογενῆ - *ton hyion ton monogenē*', 'Em perfeita coerência léxica com João 1:14 e 1:18, *monogenēs* (composto de *monos*, "único", e *genos*, "espécie/natureza", e não do verbo *gennaō*, "gerar") afirma a condição sem paralelo e incomparável de Jesus como o revelador exclusivo e supremo do Pai.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.16', 'deu', 'ἔδωκεν - *edōken*', 'Verbo no aoristo indicativo, assinalando o evento singular, definitivo e irreversível da entrega voluntária do Filho para a redenção do mundo (cf. Rm 8:32).', 3);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.16', 'o mundo', 'τὸν κόσμον - *ton kosmon*', 'O termo *kosmos* na teologia joanina representa a sociedade humana caída, alienada de Deus e imersa na escuridão. O amor divino não é desencadeado pela dignidade do objeto amado, mas expressa a pura gratuidade da graça pactual de Deus voltada a salvar a humanidade perdida.', 4);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.16', 'não pereça', 'μὴ ἀπόληται - *mē apolētai*', 'Subjuntivo aoristo médio de *apollymi*, referindo-se à ruína definitiva, condenação e exclusão final da comunhão viva com Deus.', 5);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.16', 'Fronteira do discurso e comentário do evangelista', 'R11', 'Os versículos 16 a 21 não contêm a marcação de fala de Jesus `[[J]]`. Trata-se de uma meditação teológica retrospectiva redigida pelo evangelista da perspectiva pós-pascal. As evidências textuais fundamentam essa decisão editorial: (1) o emprego do vocabulário típico do Prólogo do Evangelho (*monogenēs*, *phōs/skotos*, crer no *nome* do Filho), incomum na fala de Jesus em primeira pessoa nos evangelhos; (2) o tratamento de Deus e de Seu Filho em terceira pessoa; (3) o recurso a tempos verbais no passado e no perfeito retrospectivo (*pepisteuken* no v. 18), refletindo a experiência de uma comunidade cristã madura que contempla a Encarnação e a Páscoa como fatos consumados da história da redenção.', 6);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.17', 'JHN.3', 'JHN', 3, 17, 'οὐ γὰρ ἀπέστειλεν ὁ θεὸς τὸν υἱὸν εἰς τὸν κόσμον ἵνα κρίνῃ τὸν κόσμον, ἀλλ’ ἵνα σωθῇ ὁ κόσμος δι’ αὐτοῦ.', 'Não pois enviou o Deus o Filho ao mundo para que julgue o mundo, mas para que seja salvo o mundo por meio dele.', 'Pois Deus não enviou o Filho ao mundo para julgar o mundo, mas para que o mundo seja salvo por meio dele.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.17', 'para julgar o mundo', 'ἵνα κρίνῃ τὸν κόσμον - *hina krinē ton kosmon*', 'O verbo *krinō* carrega no contexto a nuance forense de condenar e executar veredito condenatório. As expectativas messiânicas predominantes no judaísmo do Primeiro Século aguardavam um Messias nacionalista e vingador que julgaria e aniquilaria imediatamente as nações pagãs e os ímpios. Em flagrante oposição a essa visão, o propósito originário da primeira vinda do Filho na Encarnação é a reconciliação, a cura e o resgate da criação (*hina sōthē*).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.17', 'por meio dele', 'δι’ αὐτοῦ - *di’ autou*', 'Preposição *dia* com genitivo, designando a mediação única e indispensável de Cristo na obra salvífica universal (cf. 1Tm 2:5; Jo 14:6).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.18', 'JHN.3', 'JHN', 3, 18, 'ὁ πιστεύων εἰς αὐτὸν οὐ κρίνεται· ὁ δὲ μὴ πιστεύων ἤδη κέκριται, ὅτι μὴ πεπίστευκεν εἰς τὸ ὄνομα τοῦ μονογενοῦς υἱοῦ τοῦ θεοῦ.', 'O que crê nele não é julgado; o porém que não crê já está julgado, porque não tem crido no nome do único Filho do Deus.', 'Quem nele crê não é julgado; mas quem não crê já está julgado, por não ter crido no nome do Filho único de Deus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.18', 'não é julgado', 'οὐ κρίνεται - *ou krinetai*', 'Presente passivo. Aquele que acolhe o Messias com fé é exonerado de qualquer sentença condenatória no tribunal eterno de Deus (cf. Jo 5:24; Rm 8:1).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.18', 'já está julgado', 'ἤδη κέκριται - *ēdē kekritai*', 'O perfeito passivo *kekritai* expressa uma realidade concluída e um estado judicial estabelecido no presente. O julgamento não é uma punição imposta de fora no fim dos tempos, mas a consequência intrínseca e imediata da rejeição à verdade manifesta em Cristo. A incredulidade constitui sua própria condenação existencial.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.18', 'por não ter crido', 'ὅτι μὴ πεπίστευκεν - *hoti mē pepisteuken*', 'Outro verbo no tempo perfeito grego (*pepisteuken*), denotando uma postura consolidada e deliberada de rejeição à luz.', 3);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.18', 'Filho único', 'τοῦ μονογενοῦς υἱοῦ - *tou monogenous hyiou*', 'A plenitude do título ressalta a gravidade cósmica da incredulidade: rejeitar o Filho único (*monogenēs*) significa rejeitar a revelação definitiva e insubstituível do próprio Deus invisível.', 4);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.19', 'JHN.3', 'JHN', 3, 19, 'αὕτη δέ ἐστιν ἡ κρίσις ὅτι τὸ φῶς ἐλήλυθεν εἰς τὸν κόσμον καὶ ἠγάπησαν οἱ ἄνθρωποι μᾶλλον τὸ σκότος ἢ τὸ φῶς, ἦν γὰρ αὐτῶν πονηρὰ τὰ ἔργα.', 'Este porém é o julgamento, que a luz veio ao mundo e amaram os homens mais a escuridão do que a luz; eram pois deles más as obras.', 'E o julgamento é este: a luz veio ao mundo, e os homens amaram mais a escuridão do que a luz, porque as suas obras eram más.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.19', 'o julgamento', 'ἡ κρίσις - *hē krisis*', 'Do substantivo grego *krisis*, que indica distinção, separação e decisão judicial. Na escatologia joanina, o julgamento é imanente e atua como uma crise existencial: a manifestação da luz divina (*to phōs*) revela os segredos dos corações e força cada pessoa a definir sua própria condição diante de Deus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.19', 'a escuridão', 'τὸ σκότος - *to skotos*', 'Em harmonia com a convenção léxica do projeto (cf. 1:5; 3:19), *skotos* representa a ordem corrompida e hostil à verdade de Deus.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.19', 'as suas obras eram más', 'ἦν γὰρ αὐτῶν πονηρὰ τὰ ἔργα - *ēn gar autōn ponēra ta erga*', 'O evangelista desvenda a motivação psicológica e moral da incredulidade: a resistência ao evangelho não decorre de mera dúvida intelectual ou racional, mas do apego deliberado à iniquidade, que teme ser exposta pela pureza da luz divina.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.20', 'JHN.3', 'JHN', 3, 20, 'πᾶς γὰρ ὁ φαῦλα πράσσων μισεῖ τὸ φῶς καὶ οὐκ ἔρχεται πρὸς τὸ φῶς, ἵνα μὴ ἐλεγχθῇ τὰ ἔργα αὐτοῦ·', 'Todo pois o que coisas más pratica odeia a luz e não vem para a luz, para que não sejam expostas as obras dele;', 'Pois todo aquele que pratica o mal odeia a luz e não vem para a luz, para que as suas obras não sejam expostas.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.20', 'pratica o mal', 'ὁ φαῦλα πράσσων - *ho phaula prassōn*', 'O adjetivo *phaula* refere-se a coisas vis, desprezíveis, corruptas ou destituídas de valor moral. O particípio presente *prassōn* retrata a continuidade habitual da prática perversa.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.20', 'não sejam expostas', 'ἵνα μὴ ἐλεγχθῇ - *hina mē elenchthē*', 'O verbo *elenchō* possui sentido jurídico e ético de convencer do pecado, repreender, desmascarar e trazer à plena visibilidade da verdade. Quem se entrega à iniquidade refugia-se nas sombras para evitar o confronto restaurador com a justiça divina.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.21', 'JHN.3', 'JHN', 3, 21, 'ὁ δὲ ποιῶν τὴν ἀλήθειαν ἔρχεται πρὸς τὸ φῶς, ἵνα φανερωθῇ αὐτοῦ τὰ ἔργα ὅτι ἐν θεῷ ἐστιν εἰργασμένα.', 'O porém que faz a verdade vem para a luz, para que se manifeste dele as obras que em Deus foram realizadas.', 'Mas quem faz a verdade vem para a luz, para que as suas obras se manifestem como realizadas em Deus.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.21', 'faz a verdade', 'ὁ δὲ ποιῶν τὴν ἀλήθειαν - *ho de poiōn tēn alētheian*', 'Semitismo teológico profundo que corresponde ao hebraico *''āśāh ''emet* (cf. Gn 47:29; Ne 9:33; 1Jo 1:6). A verdade (*alētheia*) na perspectiva bíblica não se esgota em enunciados conceituais ou abstrações lógicas, mas se expressa em integridade de vida, lealdade pactual e transparência moral diante de Deus e dos seres humanos.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.21', 'realizadas em Deus', 'ἐν θεῷ ἐστιν εἰργασμένα - *en theō estin eirgasmena*', 'Perfeito passivo perifrástico de *ergazomai*. Aquele que caminha na luz não busca autopromoção ou vanglória farisaica, mas anseia demonstrar que suas obras justas foram geradas, sustentadas e produzidas pela graça eficaz e pela união vital com o próprio Deus.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.22', 'JHN.3', 'JHN', 3, 22, 'Μετὰ ταῦτα ἦλθεν ὁ Ἰησοῦς καὶ οἱ μαθηταὶ αὐτοῦ εἰς τὴν Ἰουδαίαν γῆν, καὶ ἐκεῖ διέτριβεν μετ’ αὐτῶν καὶ ἐβάπτιζεν.', 'Depois destas coisas foi o Jesus e os discípulos dele para a Judeia terra, e lá permanecia com eles e batizava.', 'Depois disso, Jesus foi com os seus discípulos para a terra da Judeia; e ali passava o tempo com eles e batizava.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.22', 'terra da Judeia', 'τὴν Ἰουδαίαν γῆν - *tēn Ioudaian gēn*', 'Expressão que indica o interior agrário ou a zona rural da província da Judeia, em contraposição a Jerusalém, onde Jesus havia participado da Páscoa (Jo 2:23).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.22', 'passava o tempo com eles e batizava', 'διέτριβεν μετ’ αὐτῶν καὶ ἐβάπτιζεν - *dietriben met’ autōn kai ebaptizen*', 'Ambos os verbos encontram-se no tempo imperfeito contínuo (*dietriben*, *ebaptizen*), demonstrando uma convivência discipular prolongada e um ministério de imersão de conversos na bacia do rio Jordão. O narrador fará a ressalva em João 4:2 de que o próprio Jesus não aplicava o rito diretamente, mas Seus discípulos batizavam sob Sua liderança.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.23', 'JHN.3', 'JHN', 3, 23, 'ἦν δὲ καὶ ὁ Ἰωάννης βαπτίζων ἐν Αἰνὼν ἐγγὺς τοῦ Σαλείμ, ὅτι ὕδατα πολλὰ ἦν ἐκεῖ, καὶ παρεγίνοντο καὶ ἐβαπτίζοντο·', 'Estava porém também João batizando em Enom perto de Salim, porque águas muitas havia lá, e vinham e eram batizados;', 'João também estava batizando em Enom, perto de Salim, porque havia ali muitas águas; e as pessoas vinham e eram batizadas.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.23', 'Enom, perto de Salim', 'Αἰνὼν ἐγγὺς τοῦ Σαλείμ - *Ainōn engys tou Saleim*', 'Referência geográfica de exatidão histórica. *Ainōn* deriva da raiz aramaica *''aynowan* ("fontes abundantes" ou "mananciais"). A tradição patrística antiga (Eusébio de Cesareia e Jerônimo) localiza essa região no vale do Jordão, cerca de 13 km ao sul de Citópolis/Bete-Seã, área caracterizada por copiosas nascentes perenes.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.23', 'muitas águas', 'ὕδατα πολλὰ - *hydata polla*', 'Plural hebraizante (equivalente a *mayim rabbim*), destacando o volume hídrico imprescindível para a realização sistemática de imersões corporais completas de multidões no ambiente árido do vale do Jordão.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.24', 'JHN.3', 'JHN', 3, 24, 'οὔπω γὰρ ἦν βεβλημένος εἰς τὴν φυλακὴν ὁ Ἰωάννης.', 'Ainda não pois tinha sido lançado na prisão o João.', 'Pois João ainda não tinha sido lançado na prisão.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.24', 'ainda não tinha sido lançado na prisão', 'οὔπω γὰρ ἦν βεβλημένος εἰς τὴν φυλακήν - *oupō gar ēn beblēmenos eis tēn phylakēn*', 'Mais-que-perfeito passivo perifrástico. Nota histórica indispensável que complementa a cronologia dos Sinóticos (cf. Mc 1:14; Mt 4:12), os quais iniciam o relato do ministério galileu de Jesus após o aprisionamento de João Batista por Herodes Antipas na fortaleza de Maquero. O Quarto Evangelho resgata uma fase cronológica anterior de ministérios proféticos paralelos e coexistentes na Judeia.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.25', 'JHN.3', 'JHN', 3, 25, 'Ἐγένετο οὖν ζήτησις ἐκ τῶν μαθητῶν Ἰωάννου μετὰ Ἰουδαίου περὶ καθαρισμοῦ.', 'Surgiu então uma discussão dentre os discípulos de João com um judeu acerca de purificação.', 'Surgiu então uma discussão entre os discípulos de João e um judeu a respeito da purificação.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.25', 'discussão ... a respeito da purificação', 'ζήτησις ... περὶ καθαρισμοῦ - *zētēsis ... peri katharismou*', 'O termo *zētēsis* denota um debate teológico formal sobre interpretações legais da pureza ritual (*Halakhá*). O debate girava em torno do valor salvífico e purificador dos banhos rituais tradicionais judaicos (*mikvaot*), do batismo profético de arrependimento ministrado por João e do emergente batismo praticado pelos discípulos de Jesus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.25', 'um judeu', 'Ἰουδαίου - *Ioudaiou*', 'O texto crítico fidedigno (P66, P75, Sinaiticus, Vaticanus) adota a leitura no singular "com um judeu", enquanto manuscritos bizantinos posteriores trazem o plural "com os judeus" (*Ioudaiōn*). Em conformidade com a regra R10, o texto fluente traduz com exatidão sem inserir glosas descritivas.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.26', 'JHN.3', 'JHN', 3, 26, 'καὶ ἦλθον πρὸς τὸν Ἰωάννην καὶ εἶπαν αὐτῷ· Ῥαββί, ὃς ἦν μετὰ σοῦ πέραν τοῦ Ἰορδάνου, ᾧ σὺ μεμαρτύρηκας, ἴδε οὗτος βαπτίζει καὶ πάντες ἔρχονται πρὸς αὐτόν.', 'E foram para o João e disseram a ele: Rabi, aquele que estava contigo além do Jordão, ao qual tu tens dado testemunho, vê este batiza e todos vêm para ele.', 'Eles foram a João e lhe disseram: “Rabi, aquele que estava com você do outro lado do Jordão, de quem você deu testemunho, veja: ele está batizando, e todos vão até ele”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.26', 'do outro lado do Jordão', 'πέραν τοῦ Ἰορδάνου - *peran tou Iordanou*', 'Remissão retrospectiva a Betânia além do Jordão (Jo 1:28), cenário do batismo inicial de Jesus e do primeiro testemunho público do Batista.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.26', 'de quem você deu testemunho', 'ᾧ σὺ μεμαρτύρηκας - *hō sy memartyrēkas*', 'Perfeito ativo de *martyreō*. Os discípulos de João expressam frustração e ciúme ministerial diante do fato de que aquele a quem João autenticara e endossara publicamente agora atraía multidões maiores que as do próprio precursor.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.26', 'todos vão até ele', 'πάντες ἔρχονται πρὸς αὐτόν - *pantes erchontai pros auton*', 'Hipérbole que reflete a consternação do círculo de João diante do crescimento exponencial e incontestável do ministério de Jesus.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.27', 'JHN.3', 'JHN', 3, 27, 'ἀπεκρίθη Ἰωάννης καὶ εἶπεν· Οὐ δύναται ἄνθρωπος λαμβάνειν οὐδὲ ἓν ἐὰν μὴ ᾖ δεδομένον αὐτῷ ἐκ τοῦ οὐρανοῦ.', 'Respondeu João e disse: Não pode um homem receber nem uma só coisa se não for dado a ele do céu.', 'João respondeu e disse: “Ninguém pode receber coisa alguma, a não ser que lhe tenha sido dada do céu.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.27', 'dada do céu', 'δεδομένον ... ἐκ τοῦ οὐρανοῦ - *dedomenon ... ek tou ouranou*', 'Particípio perfeito passivo com circunlóquio judaico clássico e piedoso ("do céu" = da parte soberana de Deus). João Batista acolhe a supremacia de Jesus com serenidade espiritual: ministérios, vocações proféticas e influência espiritual não são troféus de disputa egoísta, mas dádivas outorgadas exclusivamente pela soberania e vontade do Pai.', 1);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.28', 'JHN.3', 'JHN', 3, 28, 'αὐτοὶ ὑμεῖς μοι μαρτυρεῖτε ὅτι εἶπον· Οὐκ εἰμὶ ἐγὼ ὁ χριστός, ἀλλ’ ὅτι Ἀπεσταλμένος εἰμὶ ἔμπροσθεν ἐκείνου.', 'Vós mesmos a mim testemunhais que disse: Não sou eu o Cristo, mas que: Enviado sou diante daquele.', 'Vocês mesmos me testemunham que eu disse: ‘Eu não sou o Cristo, mas fui enviado adiante dele’.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.28', 'Vocês mesmos me testemunham', 'αὐτοὶ ὑμεῖς μοι μαρτυρεῖτε - *autoi hymeis moi martyreite*', 'Uso enfático dos pronomes gregos *autoi hymeis*. O Batista relembra a sua própria confissão inicial inegociável registrada em João 1:20 ("Ele confessou e não negou; confessou: ‘Eu não sou o Cristo’").', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.28', 'fui enviado adiante dele', 'Ἀπεσταλμένος εἰμὶ ἔμπροσθεν ἐκείνου - *Apestalmenos eimi emprosthen ekeinou*', 'Perfeito passivo de *apostellō*, ecoando as profecias veterotestamentárias do mensageiro preparador da aliança (Ml 3:1; Is 40:3). A nobreza de João reside na exata consciência de seus limites e no fiel cumprimento de sua missão subordinada.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.29', 'JHN.3', 'JHN', 3, 29, 'ὁ ἔχων τὴν νύμφην νυμφίος ἐστίν· ὁ δὲ φίλος τοῦ νυμφίου ὁ ἑστηκὼς καὶ ἀκούων αὐτοῦ, χαρᾷ χαίρει διὰ τὴν φωνὴν τοῦ νυμφίου. αὕτη οὖν ἡ χαρὰ ἡ ἐμὴ πεπλήρωται.', 'O que tem a noiva noivo é; o porém amigo do noivo, o que está de pé e ouvindo a ele, com alegria se alegra por causa da voz do noivo. Esta portanto a alegria a minha foi completada.', 'Quem tem a noiva é o noivo; mas o amigo do noivo, que está presente e o ouve, alegra-se com grande alegria por causa da voz do noivo. Assim, esta minha alegria está completa.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.29', 'o amigo do noivo', 'ὁ φίλος τοῦ νυμφίου - *ho philos tou nymphiou*', 'Alusão direta à figura do *shoshbin* no contexto nupcial judaico do Primeiro Século. O *shoshbin* (o padrinho ou melhor amigo do noivo) era o encarregado de confiança responsável pelos preparativos práticos do casamento, pela proteção da noiva e pela condução do cortejo até o noivo. Ele não cobiça a noiva para si; sua maior satisfação e honra consistem em ouvir a voz exultante do noivo consumando a celebração. Na alegoria nupcial messiânica (que evoca Yahweh como o esposo de Israel no Antigo Testamento: Os 2:19-20; Is 54:5; 62:4-5), Jesus é o Noivo escatológico, o povo congregado é a Noiva, e João Batista é o dedicado *shoshbin*.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.29', 'alegra-se com grande alegria', 'χαρᾷ χαίρει - *chara chairei*', 'Construção enfática com dativo cognato (hebraísmo que expressa regozijo superlativo e pleno).', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.29', 'esta minha alegria está completa', 'αὕτη οὖν ἡ χαρὰ ἡ ἐμὴ πεπλήρωται - *hautē oun hē chara hē emē peplērōtai*', 'Perfeito passivo de *plēroō*, assinalando a consumação jubilosa e definitiva de sua vocação precursora.', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.30', 'JHN.3', 'JHN', 3, 30, 'ἐκεῖνον δεῖ αὐξάνειν, ἐμὲ δὲ ἐλαττοῦσθαι.', 'Aquele é necessário crescer, eu porém diminuir.', 'Ele deve crescer; eu, diminuir”.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.30', 'Ele deve crescer', 'δεῖ - *dei*', 'Reaparece o termo de necessidade divina irrevogável (cf. 3:7, 14). O decréscimo voluntário de João e a ascendência cósmica de Jesus atendem ao decreto soberano do Pai.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.30', 'eu, diminuir', 'ἐκεῖνον αὐξάνειν, ἐμὲ δὲ ἐλαττοῦσθαι - *ekeinon auxanein, eme de elattousthai*', 'Antítese lapidar e sublime na língua grega, que condensa o ápice da teologia joanina do testemunho. A grandeza de João Batista reside em sua autoanulação consciente diante da glória e centralidade absoluta do Messias. Com esta sentença, encerra-se formalmente o discurso de João Batista.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.31', 'JHN.3', 'JHN', 3, 31, 'Ὁ ἄνωθεν ἐρχόμενος ἐπάνω πάντων ἐστίν. ὁ ὢν ἐκ τῆς γῆς ἐκ τῆς γῆς ἐστιν καὶ ἐκ τῆς γῆς λαλεῖ· ὁ ἐκ τοῦ οὐρανοῦ ἐρχόμενος ἐπάνω πάντων ἐστίν·', 'Aquele que do alto vem acima de todos é; aquele que é da terra da terra é e da terra fala; aquele que do céu vem acima de todos é;', 'Aquele que vem do alto está acima de todos. Quem é da terra é da terra e fala da terra. Aquele que vem do céu está acima de todos.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.31', 'Aquele que vem do alto', 'Ὁ ἄνωθεν ἐρχόμενος - *Ho anōthen erchomenos*', 'O advérbio *anōthen* ("do alto", preservado conforme a decisão editorial R6 em 3:3, 7) reafirma a preexistência divina e a origem celestial transcendente do Filho. Ele está "acima de todos" (*epanō pantōn*) em dignidade, jurisdição e essência.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.31', 'é da terra e fala da terra', 'ἐκ τῆς γῆς ἐστιν καὶ ἐκ τῆς γῆς λαλεῖ - *ek tēs gēs estin kai ek tēs gēs lalei*', 'Contraste cosmológico e epistemológico intransponível entre o Criador e as criaturas. Todo mestre e profeta humano (incluindo o Batista) pertence à esfera terrena e carrega as limitações de sua origem; somente aquele que descende ontologicamente do céu pode comunicar a verdade divina em sua plenitude irrestrita.', 2);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.31', 'Fronteira do discurso e comentário do evangelista', 'R11', 'Os versículos 31 a 36 encerram o capítulo 3 com uma solene reflexão teológica do evangelista, espelhando estruturalmente a seção dos versículos 16 a 21. A transição da fala de João Batista para a reflexão do narrador é confirmada pela total afinidade vocabular e temática com o Prólogo (Jo 1:1-18) e com o comentário de 3:16-21 (*anōthen*, testemunho, doação irrestrita do Espírito, amor do Pai pelo Filho e a concessão da vida eterna).', 3);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.32', 'JHN.3', 'JHN', 3, 32, 'ὃ ἑώρακεν καὶ ἤκουσεν τοῦτο μαρτυρεῖ, καὶ τὴν μαρτυρίαν αὐτοῦ οὐδεὶς λαμβάνει.', 'O que tem visto e ouvido isto testemunha, e o testemunho dele ninguém recebe.', 'Ele testemunha o que viu e ouviu, e ninguém recebe o seu testemunho.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.32', 'o que viu e ouviu', 'ὃ ἑώρακεν καὶ ἤκουσεν - *ho heōraken kai ēkousen*', 'Verbos no perfeito e aoristo que fundamentam a revelação de Cristo em Sua condição inigualável de testemunha ocular e íntima das realidades do Pai (cf. Jo 1:18; 3:11).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.32', 'ninguém recebe o seu testemunho', 'τὴν μαρτυρίαν αὐτοῦ οὐδεὶς λαμβάνει - *tēn martyrian autou oudeis lambanei*', 'O pronome negativo universal *oudeis* ("ninguém") expõe em tom de lamento a tragédia da cegueira espiritual e da rejeição predominante do mundo humano diante da revelação de Deus (cf. Jo 1:10-11).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.33', 'JHN.3', 'JHN', 3, 33, 'ὁ λαβὼν αὐτοῦ τὴν μαρτυρίαν ἐσφράγισεν ὅτι ὁ θεὸς ἀληθής ἐστιν.', 'O que recebeu dele o testemunho selou que o Deus verdadeiro é.', 'Quem recebeu o seu testemunho confirmou com seu selo que Deus é verdadeiro.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.33', 'confirmou com seu selo', 'ἐσφράγισεν - *esphragisen*', 'Aoristo ativo de *sphragizō* ("selar", "gravar com sinete"). No mundo antigo greco-romano e semítico, estampar o selo em um documento legal significava ratificar sua autenticidade indiscutível, garantir sua validade irrevogável e prestar testemunho público de sua integridade. Quem acolhe a mensagem de Jesus atesta formalmente a fidelidade de Deus, reconhecendo que Ele cumpriu Suas promessas pactuais enviando o Seu Messias.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.33', 'Deus é verdadeiro', 'ὁ θεὸς ἀληθής ἐστιν - *ho theos alēthēs estin*', 'O adjetivo *alēthēs* designa Deus como fiel à Sua própria Palavra e veraz em todas as Suas alianças.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.34', 'JHN.3', 'JHN', 3, 34, 'ὃν γὰρ ἀπέστειλεν ὁ θεὸς τὰ ῥήματα τοῦ θεοῦ λαλεῖ, οὐ γὰρ ἐκ μέτρου δίδωσιν τὸ πνεῦμα.', 'Aquele pois que enviou o Deus as palavras do Deus fala, não pois por medida dá o Espírito.', 'Pois aquele que Deus enviou fala as palavras de Deus, porque ele não dá o Espírito por medida.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.34', 'fala as palavras de Deus', 'τὰ ῥήματα τοῦ θεοῦ λαλεῖ - *ta rhēmata tou theou lalei*', 'O substantivo *rhēmata* designa as palavras vivas e declarações orais diretas. Sendo o Enviado por excelência do Pai, os ensinamentos de Jesus são a própria locução e autoridade de Deus em pessoa (cf. Jo 12:49-50; 14:10).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.34', 'não dá o Espírito por medida', 'οὐ γὰρ ἐκ μέτρου δίδωσιν τὸ πνεῦμα - *ou gar ek metrou didōsin to pneuma*', 'A tradição rabínica do judaísmo do Segundo Templo ensinava que os profetas e sábios do Antigo Testamento recebiam o Espírito de Deus em porções parciais, finitas e distribuídas conforme a capacidade de cada um (*Levítico Rabá* 15:2). Em nítido contraste, Deus Pai concede ao Filho a plenitude absoluta, contínua e incomensurável do Espírito Santo, capacitando-O para Sua missão messiânica universal.', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.35', 'JHN.3', 'JHN', 3, 35, 'ὁ πατὴρ ἀγαπᾷ τὸν υἱόν, καὶ πάντα δέδωκεν ἐν τῇ χειρὶ αὐτοῦ.', 'O Pai ama o Filho, e todas as coisas tem dado na mão dele.', 'O Pai ama o Filho e entregou todas as coisas em suas mãos.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.35', 'O Pai ama o Filho', 'ὁ πατὴρ ἀγαπᾷ τὸν υἱόν - *ho patēr agapa ton hyion*', 'A comunhão amorosa eterna (*agapē*) entre o Pai e o Filho constitui o motor gerador da revelação e da redenção cósmica no Quarto Evangelho (cf. Jo 5:20; 17:24).', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.35', 'entregou todas as coisas em suas mãos', 'πάντα δέδωκεν ἐν τῇ χειρὶ αὐτοῦ - *panta dedōken en tē cheiri autou*', 'Perfeito ativo *dedōken*. Semitismo idiomático que expressa a transferência irrevogável de senhorio, julgamento e jurisdição soberana universal sobre toda a criação para as mãos do Filho (cf. Jo 13:3; Mt 28:18; Hb 1:2-3).', 2);
INSERT INTO verses (id, chapter_id, book_id, chapter_number, verse_number, greek_text, literal_text, translation_text) VALUES ('JHN.3.36', 'JHN.3', 'JHN', 3, 36, 'ὁ πιστεύων εἰς τὸν υἱὸν ἔχει ζωὴν αἰώνιον· ὁ δὲ ἀπειθῶν τῷ υἱῷ οὐκ ὄψεται ζωήν, ἀλλ’ ἡ ὀργὴ τοῦ θεοῦ μένει ἐπ’ αὐτόν.', 'O que crê no Filho tem vida eterna; o porém que desobedece ao Filho não verá vida, mas a ira do Deus permanece sobre ele.', 'Quem crê no Filho tem a vida eterna; mas quem desobedece ao Filho não verá a vida, e a ira de Deus permanece sobre ele.');
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.36', 'Quem crê ... mas quem desobedece', 'ὁ πιστεύων ... ὁ δὲ ἀπειθῶν - *ho pisteuōn ... ho de apeithōn*', 'A oposição construída pelo evangelista não se dá entre crer (*pisteuō*) e um mero "descrer" intelectual (*apisteō*), mas entre crer e *desobedecer* (*apeitheō*). Na teologia bíblica pactual, a fé genuína (*pistis*) não é um mero consentimento mental passivo a proposições teóricas, mas uma atitude ativa de submissão pactual, compromisso moral e lealdade pessoal a Cristo. Recusar a fé é, portanto, um ato deliberado de desobediência e insubordinação contra a verdade de Deus.', 1);
INSERT INTO verse_notes (verse_id, term, greek_lemma, explanation, order_index) VALUES ('JHN.3.36', 'a ira de Deus permanece sobre ele', 'ἡ ὀργὴ τοῦ θεοῦ μένει ἐπ’ αὐτόν - *hē orgē tou theou menei ep’ auton*', 'Única ocorrência da expressão "a ira de Deus" (*hē orgē tou theou*) em todo o Evangelho de João. A ira divina na revelação bíblica não expressa uma reação emocional descontrolada, vingativa ou arbitrária, mas a oposição santa, imutável e judicial da retidão de Deus contra a iniquidade e a impenitência. O tempo presente do verbo *menei* ("permanece") indica que a humanidade alienada já se encontra naturalmente sob a sentença do juízo divino; a fé no Filho é a única via de livramento que conduz à vida eterna (*zōē aiōnios*).', 2);
